/* Tıbbi Mikrobiyoloji Soru Bankası
   k = konu, s = soru, c = cevap
   Yeni soru eklemek için listenin sonuna aynı formatta satır ekleyin. */
const SORULAR = [
/* ---------------- BAKTERİYOLOJİ ---------------- */
{k:"Bakteriyoloji",s:"Gram boyamada kristal viyole–iyot kompleksini hücre duvarında tutan yapı nedir ve neden Gram pozitifler mor kalır?",c:"Kalın peptidoglikan tabaka (20–80 nm) ve teikoik asitler. Alkol-aseton dekolorizasyonunda kalın peptidoglikan dehidrate olup porları büzülür, kristal viyole–iyot kompleksi dışarı kaçamaz; Gram negatiflerde ince peptidoglikan + dış membranın lipidleri alkolle çözünerek kompleks yıkanır ve safranin ile pembe boyanırlar."},
{k:"Bakteriyoloji",s:"Katalaz ve koagülaz testleri Gram pozitif koklarda ayırımı nasıl yapar?",c:"Katalaz (+) → Staphylococcus; katalaz (−) → Streptococcus/Enterococcus. Katalaz (+) suşlarda koagülaz (+) → S. aureus; koagülaz (−) → KNS (S. epidermidis, S. saprophyticus vb.). Koagülaz için lam testi klumping faktörü (bağlı koagülaz), tüp testi serbest koagülazı gösterir; lam testi negatifse tüp testi ile doğrulanır."},
{k:"Bakteriyoloji",s:"Novobiyosin direnci hangi stafilokoku tanımlar ve klinik önemi nedir?",c:"S. saprophyticus novobiyosine dirençlidir (zon ≤16 mm). Genç, cinsel olarak aktif kadınlarda sistit/ÜSE'nin ikinci sık etkenidir; S. epidermidis ise novobiyosine duyarlıdır."},
{k:"Bakteriyoloji",s:"Optokin ve basitrasin duyarlılığı streptokok ayırımında nasıl kullanılır?",c:"Alfa hemolitik: optokin duyarlı + safra ile erime (+) → S. pneumoniae; optokin dirençli → viridans grubu. Beta hemolitik: basitrasin (0.04 U) duyarlı + PYR (+) → S. pyogenes (Grup A); basitrasin dirençli + CAMP (+) + hippurat (+) → S. agalactiae (Grup B)."},
{k:"Bakteriyoloji",s:"CAMP testinin prensibi nedir?",c:"S. agalactiae'nin ürettiği CAMP faktörü, S. aureus'un beta-hemolizininin (sfingomiyelinaz) kısmen parçaladığı eritrosit membranını tamamlayarak sinerjik, ok ucu (kama) şeklinde bir hemoliz alanı oluşturur. Listeria monocytogenes de düz çizgi şeklinde pozitif CAMP verir."},
{k:"Bakteriyoloji",s:"Enterococcus ile Streptococcus bovis (S. gallolyticus) ayırımı nasıl yapılır ve S. bovis bakteriyemisi neyi düşündürür?",c:"Her ikisi de safra-eskülin (+); ancak %6.5 NaCl'de üreme ve PYR testi Enterococcus'ta (+), S. bovis'te (−)'dir. S. bovis bakteriyemisi/endokarditi kolon karsinomu ile güçlü ilişkilidir; kolonoskopi endikedir."},
{k:"Bakteriyoloji",s:"MRSA'nın moleküler mekanizması nedir ve laboratuvarda nasıl saptanır?",c:"SCCmec kaset üzerindeki mecA (veya mecC) geni, beta-laktamlara düşük afiniteli PBP2a üretir. Saptama: sefoksitin disk difüzyon (30 µg, zon ≤21 mm dirençli), sefoksitin/oksasilin MİK, PBP2a lateks aglütinasyonu veya mecA PCR (altın standart)."},
{k:"Bakteriyoloji",s:"D-testi neyi gösterir ve nasıl yorumlanır?",c:"İndüklenebilir klindamisin direncini (iMLSb, erm geni) gösterir. Eritromisin ve klindamisin diskleri 15–26 mm arayla konur; klindamisin zonunun eritromisine bakan tarafında düzleşme (D harfi) görülürse klindamisin in vitro duyarlı görünse bile tedavide kullanılmamalıdır."},
{k:"Bakteriyoloji",s:"Corynebacterium diphtheriae için hangi besiyerleri ve hangi toksin testi kullanılır?",c:"Besiyeri: Löffler serum besiyeri (metakromatik Babeş-Ernst granülleri, Albert/Neisser boyası), sistin-tellürit (Tinsdale) agarda siyah koloni + kahverengi hale. Toksijenite: Elek immünodifüzyon testi (presipitasyon çizgileri) veya tox geni PCR."},
{k:"Bakteriyoloji",s:"Listeria monocytogenes'in mikrobiyolojik ayırıcı özellikleri nelerdir?",c:"Gram pozitif, sporsuz basil; 4°C'de üreme (soğukta zenginleştirme), 20–25°C'de peritriş flagella ile 'takla atan' hareket (tumbling motility), dar zonlu beta hemoliz, katalaz (+), eskülin (+), CAMP (+). Gebe, yenidoğan, yaşlı ve immünsüpresiflerde menenjit/sepsis yapar; tedavide ampisilin ± gentamisin (sefalosporinlere doğal dirençli)."},
{k:"Bakteriyoloji",s:"Bacillus anthracis ile Bacillus cereus'u ayıran temel özellikler nelerdir?",c:"B. anthracis: hareketsiz, kanlı agarda hemolizsiz, penisiline duyarlı, kapsüllü (poli-D-glutamik asit), 'medusa başı' koloni, string of pearls testi (+). B. cereus: hareketli, beta hemolitik, penisiline dirençli, kapsülsüz; emetik (serebrozit, pişmiş pilav) ve diyareik toksin üretir."},
{k:"Bakteriyoloji",s:"Clostridioides difficile enfeksiyonunda laboratuvar tanı algoritması nasıldır?",c:"İki aşamalı: önce yüksek duyarlılıklı GDH antijeni (ve/veya NAAT), ardından yüksek özgüllüklü toksin A/B EIA. GDH(+)/Toksin(+) → CDI; GDH(−)/Toksin(−) → dışla; uyumsuzsa NAAT ile çöz. Yalnız şekilsiz/sulu dışkı test edilir; tedavi takibi için test tekrarlanmaz (kolonizasyon yanıltır)."},
{k:"Bakteriyoloji",s:"Tetanoz ve botulizm toksinlerinin etki mekanizmaları nasıl farklıdır?",c:"Her ikisi de çinko-bağımlı endopeptidazdır ve SNARE proteinlerini keser. Tetanospazmin (sinaptobrevin/VAMP) inhibitör nöronlarda (Renshaw) GABA/glisin salınımını engeller → spastik paralizi. Botulinum toksini (SNAP-25, sintaksin) periferik kolinerjik uçlarda asetilkolin salınımını engeller → flask (gevşek) paralizi."},
{k:"Bakteriyoloji",s:"Neisseria gonorrhoeae ile N. meningitidis'i biyokimyasal olarak ne ayırır?",c:"Karbonhidrat kullanımı: gonokok yalnız glukozu (G), meningokok glukoz + maltozu (GM) asitlendirir. M. catarrhalis hiçbirini kullanmaz ama DNaz (+) ve butirat esteraz (+)'dir. Meningokok kapsüllüdür ve nazofarenkste taşınır; gonokok kapsülsüzdür."},
{k:"Bakteriyoloji",s:"Thayer-Martin (VCN/VCNT) besiyerinde hangi antibiyotikler bulunur ve ne işe yarar?",c:"Vankomisin (Gram pozitifleri), kolistin (Gram negatif kontaminantları), nistatin/anisomisin (mantarları), trimetoprim (Proteus yayılmasını) baskılar. Çikolata agar temellidir; Neisseria'nın seçici izolasyonunda kullanılır. Not: Vankomisine duyarlı bazı gonokok suşları baskılanabilir."},
{k:"Bakteriyoloji",s:"Haemophilus influenzae'nin X ve V faktör gereksinimi nedir; satellitizm nasıl oluşur?",c:"X faktörü = hemin (protoporfirin IX), V faktörü = NAD/NADP. H. influenzae her ikisine de gereksinim duyar, bu nedenle kanlı agarda üremez, çikolata agarda ürer. S. aureus NAD salgıladığı için kanlı agarda stafilokok kolonisi çevresinde uydu (satellit) koloniler oluşur."},
{k:"Bakteriyoloji",s:"Bordetella pertussis için örnek alma ve besiyeri seçimi nasıl olmalıdır?",c:"Nazofaringeal aspirat veya kalsiyum aljinat/Dacron eküvyon (pamuk yağ asitleri inhibe eder). Besiyeri: Bordet-Gengou (kanlı gliserin-patates) veya Regan-Lowe (kömürlü, sefaleksinli). Altın standart pratikte PCR'dir; kültür duyarlılığı kataral dönemde en yüksektir."},
{k:"Bakteriyoloji",s:"Legionella pneumophila tanısında hangi yöntemler kullanılır?",c:"İdrarda Legionella antijeni (yalnız serogrup 1'i saptar, hızlı), BCYE agarda kültür (L-sistein ve demir gerektirir; alt solunum yolu örneği), DFA, PCR ve çift serum örneğinde 4 kat antikor artışı. Rutin besiyerlerinde üremez; Gram boyamada zor görülür."},
{k:"Bakteriyoloji",s:"Enterobacterales içinde laktoz pozitif ve negatif başlıca cinsler hangileridir?",c:"Laktoz (+): E. coli, Klebsiella, Enterobacter, Citrobacter, Serratia (geç/zayıf). Laktoz (−): Salmonella, Shigella, Proteus, Yersinia, Edwardsiella. MacConkey'de laktoz (+) pembe, (−) renksiz koloni; EMB'de E. coli metalik yeşil parlaklık verir."},
{k:"Bakteriyoloji",s:"TSI (Üçlü Şekerli Demir) agarda K/A, gaz ve H2S ne anlama gelir?",c:"Yatık/dip = K/A: yalnız glukoz fermente (Shigella, Salmonella); A/A: glukoz+laktoz ve/veya sükroz fermente (E. coli, Klebsiella); K/K: fermentasyon yok (Pseudomonas). Siyah renk = H2S (Salmonella, Proteus, Citrobacter); besiyerinde çatlak/kabarcık = gaz üretimi."},
{k:"Bakteriyoloji",s:"IMViC testleri E. coli ile Klebsiella'yı nasıl ayırır?",c:"İndol, Metil kırmızısı, Voges-Proskauer, Sitrat. E. coli: + + − −; Klebsiella/Enterobacter: − − + +. E. coli karışık asit fermentasyonu yapar (düşük pH → MR+), Klebsiella butandiol yolunu kullanır (asetoin → VP+)."},
{k:"Bakteriyoloji",s:"EHEC (E. coli O157:H7) tanısında hangi besiyeri ve hangi özellik kullanılır?",c:"Sorbitol MacConkey (SMAC) agar: O157:H7 sorbitolü fermente etmez, renksiz koloni verir (diğer E. coli'ler pembe). Doğrulama: O157 ve H7 antiserumları, Shiga toksin (Stx1/Stx2) EIA veya PCR. HÜS riski nedeniyle antibiyotik ve antimotilite ilaçlarından kaçınılır."},
{k:"Bakteriyoloji",s:"Salmonella Typhi'de hastalık haftalarına göre hangi örnek en verimlidir?",c:"1. hafta: kan kültürü (%80-90); 2-3. hafta: dışkı ve idrar kültürü, Widal titreleri; kemik iliği kültürü antibiyotik altında bile en duyarlı yöntemdir (%90+). Kronik taşıyıcılıkta safra/duodenal aspirat ve Vi antikoru değerlidir."},
{k:"Bakteriyoloji",s:"Shigella türleri ve serogrupları nelerdir?",c:"A: S. dysenteriae (Shiga toksin, en ağır), B: S. flexneri, C: S. boydii, D: S. sonnei (gelişmiş ülkelerde en sık, tek serotip, geç laktoz pozitif). Hepsi hareketsiz, laktoz (−), H2S (−); çok düşük infeksiyöz doz (10-100 basil) ile bulaşır."},
{k:"Bakteriyoloji",s:"Proteus mirabilis'in tanımlayıcı laboratuvar özellikleri nelerdir?",c:"Kanlı agarda yayılma (swarming), yoğun üreaz aktivitesi (idrar pH'sını yükseltip strüvit taşı yapar), H2S (+), fenilalanin deaminaz (+), 'çürük/yanık' kokusu. P. mirabilis indol (−), P. vulgaris indol (+)'dir."},
{k:"Bakteriyoloji",s:"Pseudomonas aeruginosa'yı tanımlayan fenotipik özellikler nelerdir?",c:"Gram negatif, oksidaz (+), nonfermentatif (glukozu okside eder), 42°C'de ürer, piyosiyanin (mavi-yeşil) ve piyoverdin (floresan) pigmenti, üzüm/mısır kokusu, kanlı agarda metalik parlaklık ve beta hemoliz. Nemli ortam ve dezenfektanlara dirençlidir."},
{k:"Bakteriyoloji",s:"Vibrio cholerae kültüründe hangi besiyeri kullanılır ve toksin nasıl etki eder?",c:"TCBS agar: sükroz (+) sarı koloni (V. cholerae), sükroz (−) yeşil koloni (V. parahaemolyticus). Alkali peptonlu su ile zenginleştirilir. Kolera toksini (AB5) A alt birimi Gs proteinini ADP-ribozile eder → adenilat siklaz kalıcı aktif → cAMP ↑ → klorür sekresyonu ve masif sulu ishal."},
{k:"Bakteriyoloji",s:"Campylobacter jejuni'nin kültür koşulları nasıldır?",c:"Skirrow/Butzler/CCDA seçici besiyerinde, 42°C'de, mikroaerofilik ortamda (%5 O2, %10 CO2, %85 N2) üretilir. Gram boyamada 'martı kanadı' görünümü, oksidaz (+), katalaz (+), hipurat hidroliz (+) (C. jejuni'yi C. coli'den ayırır). Guillain-Barré sendromu ile ilişkilidir."},
{k:"Bakteriyoloji",s:"Helicobacter pylori tanısında invaziv ve non-invaziv testler nelerdir?",c:"İnvaziv: hızlı üreaz (CLO) testi, histopatoloji, kültür (antibiyotik duyarlılığı için), doku PCR. Non-invaziv: üre nefes testi (C13/C14), dışkıda antijen, serolojik antikor (eradikasyon takibinde kullanılmaz). Test öncesi PPI 2 hafta, antibiyotik 4 hafta kesilmelidir."},
{k:"Bakteriyoloji",s:"Brucella tanısında hangi serolojik testler ve hangi kültür yöntemi kullanılır?",c:"Rose Bengal (tarama), standart tüp aglütinasyonu (STA/Wright ≥1/160 anlamlı), Coombs'lu Brucella testi (blokan IgG antikorları için), Brucellacapt, ELISA. Kültür: kan/kemik iliği, otomatize sistemlerde 7-10 gün (klasik Castaneda bifazik). Prozon fenomeni nedeniyle serum mutlaka ileri dilüsyonlara kadar çalışılmalıdır."},
{k:"Bakteriyoloji",s:"Francisella tularensis'in laboratuvar riski ve tanısı nasıldır?",c:"Biyogüvenlik düzeyi 3 patojenidir; laboratuvarda aerosolle bulaş riski yüksektir, şüphede laboratuvar uyarılmalıdır. Sistein/sistin içeren besiyeri (çikolata, BCYE) gerekir. Pratikte tanı seroloji (mikroaglütinasyon ≥1/160 veya 4 kat artış) ve PCR ile konur."},
{k:"Bakteriyoloji",s:"Mycobacterium tuberculosis için ARB boyama yöntemleri ve duyarlılık sınırı nedir?",c:"Ziehl-Neelsen (sıcak karbol fuksin), Kinyoun (soğuk) ve auramin-rodamin floresan boyama (daha duyarlı, taramada tercih). Mikroskopi için mL'de 5.000-10.000 basil gerekir; kültür için 10-100 basil yeterlidir. Asidorezistans mikolik asit-arabinogalaktan yapısına bağlıdır."},
{k:"Bakteriyoloji",s:"Tüberküloz kültüründe katı ve sıvı besiyerleri nelerdir, süreleri ne kadardır?",c:"Katı: Löwenstein-Jensen (yumurta bazlı), Middlebrook 7H10/7H11 (agar bazlı) — 3-8 hafta. Sıvı otomatize: MGIT 960, BACTEC — 1-3 hafta, daha duyarlı. Örnek önce NALC-NaOH ile dekontamine ve homojenize edilir. Hızlı tanı için Xpert MTB/RIF (rifampisin direncini de saptar)."},
{k:"Bakteriyoloji",s:"Nocardia ile Actinomyces'i ayıran temel özellikler nelerdir?",c:"Nocardia: aerop, kısmi asidorezistan (modifiye Kinyoun +), toprakta bulunur, immünsüpresiflerde akciğer/beyin apsesi, tedavi TMP-SMX. Actinomyces: anaerop/mikroaerofilik, asidorezistan değil, normal ağız florası, servikofasiyal 'kükürt granüllü' apse ve sinüs yolları, tedavi yüksek doz penisilin."},
{k:"Bakteriyoloji",s:"Anaerop kültür için örnek alma ve taşımada nelere dikkat edilir?",c:"Aspirasyonla sıvı/doku örneği alınır (eküvyon son tercih), hava kabarcığı çıkarılır, anaerop taşıma besiyerinde 30 dakika içinde laboratuvara ulaştırılır, buzdolabına konmaz. Kontamine olabilecek örnekler (balgam, vajinal sürüntü, dışkı, idrar) anaerop kültüre gönderilmez."},
{k:"Bakteriyoloji",s:"Bacteroides fragilis grubunun ayırıcı özellikleri ve direnç mekanizması nedir?",c:"Safraya dirençli (BBE agarda ürer, eskülin hidrolizi ile siyahlaşma), kanamisin-vankomisin-kolistin disklerine dirençli, kapsüllü (apse oluşumunda rol alır). cepA/cfiA beta-laktamazları penisiline direnç sağlar; tedavi metronidazol, karbapenem, beta-laktam/beta-laktamaz inhibitörü kombinasyonlarıdır."},
{k:"Bakteriyoloji",s:"Treponema pallidum doğrudan tanısında hangi yöntemler kullanılır?",c:"Karanlık saha mikroskobisi (şankr eksudası; oral lezyonlarda komensal treponemalar nedeniyle güvenilmez), DFA-TP, lezyon örneğinde PCR ve doku için gümüşleme (Warthin-Starry) veya immünohistokimya. Rutin besiyerinde üretilemez."},
{k:"Bakteriyoloji",s:"Leptospirozda tanı zamanlamasına göre hangi test kullanılır?",c:"İlk hafta (leptospiremik dönem): kan ve BOS kültürü (EMJH besiyeri), PCR. 2. haftadan sonra: idrar kültürü/PCR ve seroloji — altın standart mikroskobik aglütinasyon testi (MAT), tarama için IgM ELISA. Çift serumda 4 kat titre artışı tanı koydurur."},
{k:"Bakteriyoloji",s:"Borrelia burgdorferi (Lyme) serolojisinde iki basamaklı algoritma nasıldır?",c:"1. basamak: ELISA/IFA (duyarlı). Pozitif veya sınırda ise 2. basamak: Western blot — IgM için 3 banttan 2'si (23, 39, 41 kDa), IgG için 10 banttan 5'i pozitif olmalı. Alternatif olarak modifiye iki-ELISA (MTTT) kullanılır. Erken lokalize evrede (eritema migrans) seroloji negatif olabilir, tanı kliniktir."},
{k:"Bakteriyoloji",s:"Mycoplasma pneumoniae'nin mikrobiyolojik özellikleri ve tanısı nedir?",c:"Hücre duvarı yoktur (sterol içeren membran), bu nedenle Gram boyanmaz ve beta-laktamlara doğal dirençlidir. Kültürde 'sahanda yumurta' koloni, uzun sürer. Tanı: PCR (tercih), IgM serolojisi, soğuk aglütininler (özgül değil). Tedavi: makrolid, doksisiklin, florokinolon."},
{k:"Bakteriyoloji",s:"Chlamydia trachomatis tanısında altın standart nedir ve serovarlar hangi hastalıklarla ilişkilidir?",c:"Altın standart NAAT (idrar veya genital sürüntü). Serovarlar: A-C trahom, D-K ürogenital enfeksiyon/inklüzyon konjonktiviti/yenidoğan pnömonisi, L1-L3 lenfogranuloma venereum. Zorunlu hücre içi bakteridir; elemanter cisim (infeksiyöz) ve retiküler cisim (replikatif) formları vardır."},
{k:"Bakteriyoloji",s:"Rickettsia enfeksiyonlarında Weil-Felix testi nedir ve neden terk edilmiştir?",c:"Proteus vulgaris OX-19, OX-2 ve OX-K antijenleri ile riketsiyal antikorların çapraz aglütinasyonuna dayanır. Duyarlılık ve özgüllüğü düşüktür; yerini IFA (altın standart, çift serumda 4 kat artış), PCR ve deri biyopsisinde immünohistokimya almıştır."},
{k:"Bakteriyoloji",s:"ESBL saptamasında hangi fenotipik test kullanılır?",c:"Kombine disk testi: seftazidim ve sefotaksim disklerinin tek başına ve klavulanat ile birlikte zon çapları karşılaştırılır; klavulanatlı diskte ≥5 mm artış ESBL lehinedir. Alternatif: çift disk sinerji testi (amoksisilin-klavulanat merkezde, 'şampanya mantarı' görünümü) ve gradyan strip testleri."},
{k:"Bakteriyoloji",s:"Karbapenemaz sınıfları nelerdir ve hangi testlerle ayrılır?",c:"Ambler A (KPC – klavulanat/avibaktam ile inhibe), B (metallo-beta-laktamaz: NDM, VIM, IMP – EDTA/dipikolinik asit ile inhibe, aztreonamı hidroliz etmez), D (OXA-48 – zayıf karbapenemaz, temosilin direnci ipucu). Testler: modifiye Hodge (terk edilmekte), mCIM/eCIM, kolorimetrik (Carba NP), immünokromatografik hızlı testler, PCR."},
{k:"Bakteriyoloji",s:"Kan kültüründe kontaminasyonu gerçek bakteriyemiden ayıran ipuçları nelerdir?",c:"Birden fazla şişe/set pozitifliği, kısa üreme süresi (<24 saat), klinik uyum, etkenin türü (S. aureus, S. pneumoniae, E. coli, Candida neredeyse her zaman anlamlı; KNS, Corynebacterium, Bacillus, Cutibacterium çoğunlukla kontaminant), yabancı cisim varlığı ve eşzamanlı kateter-periferik kültür fark süresi (DTP >2 saat kateter enfeksiyonu lehine)."},
{k:"Bakteriyoloji",s:"İdrar kültüründe anlamlı bakteriüri sınırları nasıl değerlendirilir?",c:"Orta akım idrarda asemptomatik bakteriüri ≥10^5 KOB/mL (iki ardışık örnek, kadınlarda), akut sistitte ≥10^3, akut piyelonefritte ≥10^4, kateterli hastada ≥10^3 KOB/mL anlamlı kabul edilir. Suprapubik aspiratta herhangi bir üreme anlamlıdır; üçten fazla tür üremesi kontaminasyon lehinedir."},
{k:"Bakteriyoloji",s:"Balgam örneğinin kalitesi mikroskobik olarak nasıl değerlendirilir?",c:"Bartlett/Murray-Washington kriterleri: 100x büyütmede alanda <10 epitel hücresi ve >25 lökosit olması kaliteli alt solunum yolu örneğini gösterir. Epitel hücresi fazlaysa örnek tükürükle kontamine kabul edilip reddedilir (Legionella ve mikobakteri şüphesi hariç)."},
{k:"Bakteriyoloji",s:"MALDI-TOF MS bakteri tanımlamasında nasıl çalışır ve sınırlılıkları nelerdir?",c:"Matriks ile kristalize edilen bakterinin ribozomal proteinleri lazerle iyonize edilir; uçuş süresine göre kütle/yük spektrumu çıkarılıp referans kütüphaneyle karşılaştırılır. Dakikalar içinde tür düzeyinde tanı verir. Sınırlılık: yakın akraba türlerde (S. pneumoniae/viridans, Shigella/E. coli) ayrım güçlüğü, direnç hakkında doğrudan bilgi vermemesi, zengin kütüphane gereksinimi."},
{k:"Bakteriyoloji",s:"MİK, MBK ve tolerans kavramlarını açıklayın.",c:"MİK: gözle görülür üremeyi engelleyen en düşük antibiyotik konsantrasyonu. MBK: başlangıç inokulumunun ≥%99.9'unu öldüren en düşük konsantrasyon. MBK/MİK oranı ≥32 ise tolerans vardır (bakterisidal ilaç bakteriyostatik davranır); endokardit gibi tabloların tedavi başarısızlığında rol oynar."},
{k:"Bakteriyoloji",s:"Antibiyotik direncinin başlıca biyokimyasal mekanizmaları nelerdir?",c:"1) Enzimatik inaktivasyon (beta-laktamaz, aminoglikozid modifiye edici enzimler), 2) Hedef değişimi (PBP2a, ribozomal metilasyon-erm, DNA giraz mutasyonu, vanA ile D-Ala-D-Lak), 3) Geçirgenlik azalması (porin kaybı – OprD), 4) Aktif atım pompaları (efluks – MexAB, TetA), 5) Hedefin aşırı üretimi veya alternatif yol (dihidrofolat redüktaz)."},
{k:"Bakteriyoloji",s:"Vankomisin direnci fenotipleri (VanA, VanB, VanC) nasıl ayrılır?",c:"VanA: vankomisin ve teikoplanin dirençli, indüklenebilir, plazmid/transpozon (Tn1546) kaynaklı, E. faecium'da sık. VanB: vankomisin dirençli, teikoplanin duyarlı. VanC: E. gallinarum/E. casseliflavus'ta doğal, düşük düzey, kromozomal. VanA/B'de D-Ala-D-Ala yerine D-Ala-D-Laktat sentezlenir, afinite 1000 kat azalır."},
{k:"Bakteriyoloji",s:"Bakteriyel sporun yapısı ve direncinin nedeni nedir?",c:"Çekirdek (dehidrate, dipikolinik asit-kalsiyum kompleksi ve küçük asit çözünür proteinler DNA'yı korur), iç membran, korteks (gevşek peptidoglikan), spor kılıfı (keratin benzeri protein) ve eksosporium. Su içeriğinin azlığı ve DPA-Ca ısıya, radyasyona, kimyasallara direnç sağlar; otoklav (121°C, 15 dk) ile inaktive olur."},
{k:"Bakteriyoloji",s:"Endotoksin ve ekzotoksin farkları nelerdir?",c:"Endotoksin: Gram negatiflerin dış membranındaki lipopolisakkaritin lipid A parçası; ısıya dayanıklı, zayıf immünojen, toksoid yapılamaz, TLR4 üzerinden sitokin fırtınası ve septik şok yapar. Ekzotoksin: salgılanan protein; ısıya duyarlı, güçlü immünojen, toksoid yapılabilir, özgül hücresel hedefleri ve düşük etkin dozu vardır."},
{k:"Bakteriyoloji",s:"Süperantijen nedir ve hangi bakteriler üretir?",c:"MHC klas II'nin dışına ve T hücre reseptörünün Vβ bölgesine köprü kurarak antijene özgü olmayan yolla T hücrelerinin %5-30'unu poliklonal aktive eden toksinlerdir; masif IL-2, IFN-γ, TNF salınımı ile şok tablosu yapar. Örnek: S. aureus TSST-1 ve enterotoksinleri, S. pyogenes SpeA/SpeC."},
{k:"Bakteriyoloji",s:"Biyofilmin klinik önemi ve direnç mekanizması nedir?",c:"Ekzopolisakkarit matriks içinde yaşayan bakteri topluluğudur; kateter, protez, kalp kapağı gibi yabancı cisimlerde oluşur. Direnç nedenleri: antibiyotiğin matrikse penetre olamaması, derin tabakada metabolik yavaşlama (persister hücreler), quorum sensing ile gen ekspresyonu değişimi ve fagositozdan korunma. Genellikle materyalin çıkarılması gerekir."},
{k:"Bakteriyoloji",s:"Konjugasyon, transdüksiyon ve transformasyon arasındaki farklar nelerdir?",c:"Konjugasyon: pilus aracılığıyla hücreden hücreye plazmid/transpozon aktarımı (direnç genlerinin ana yayılım yolu). Transdüksiyon: bakteriyofaj aracılığıyla DNA aktarımı (genelleşmiş/özelleşmiş); difteri ve kolera toksin genleri böyle taşınır. Transformasyon: ortamdaki çıplak DNA'nın kompetent bakteriye alınması (S. pneumoniae, Neisseria, Haemophilus)."},
{k:"Bakteriyoloji",s:"Kanlı agarda hemoliz tipleri nasıl tanımlanır?",c:"Alfa: kısmi hemoliz, koloni çevresinde yeşilimsi renk (pnömokok, viridans). Beta: tam hemoliz, berrak zon (S. pyogenes, S. agalactiae). Gama: hemoliz yok (bazı enterokoklar). Streptolizin O oksijene duyarlıdır, bu nedenle S. pyogenes'te derin ekimde hemoliz daha belirgin görülür."},
{k:"Bakteriyoloji",s:"Kolistin duyarlılığı neden disk difüzyonla çalışılmaz?",c:"Kolistin büyük ve katyonik bir moleküldür, agarda yeterince difüze olmaz; disk difüzyon ve gradyan test sonuçları güvenilmezdir. EUCAST/CLSI broth mikrodilüsyonu (ISO 20776-1) tek referans yöntem olarak önerir. Ayrıca mcr-1 gibi plazmid aracılı direnç genleri düşük düzey direnç yapıp gözden kaçabilir."},
{k:"Bakteriyoloji",s:"Kirby-Bauer disk difüzyon testinde standardizasyon parametreleri nelerdir?",c:"Mueller-Hinton agar 4 mm derinlik, pH 7.2-7.4, 0.5 McFarland inokulum (≈1.5x10^8 KOB/mL) 15 dakika içinde ekim, diskler arası ≥24 mm, 35±2°C'de 16-18 saat, ambient hava (bazı bakterilerde %5 CO2). Katyon ayarlı MH aminoglikozid ve kolistin için, MH-F (at kanı + NAD) zor üreyenler için kullanılır."},
{k:"Bakteriyoloji",s:"Hastane kaynaklı Acinetobacter baumannii'nin mikrobiyolojik özellikleri nelerdir?",c:"Gram negatif kokobasil (Gram boyamada Neisseria ile karışabilir), oksidaz (−), nonfermentatif, hareketsiz, kuru yüzeylerde uzun süre canlı kalır. Karbapenem direnci çoğunlukla OXA-23/OXA-24 gibi sınıf D karbapenemazlara bağlıdır; tedavide kolistin, sulbaktam kombinasyonları ve yeni ajanlar kullanılır."},
{k:"Bakteriyoloji",s:"Stenotrophomonas maltophilia'nın ayırt edici direnci nedir?",c:"L1 (metallo-beta-laktamaz) ve L2 (serin sefalosporinaz) enzimleri nedeniyle karbapenemler dahil neredeyse tüm beta-laktamlara doğal dirençlidir. Seçilecek tedavi TMP-SMX'tir; alternatifler levofloksasin, minosiklin, seftazidim-avibaktam+aztreonam. Oksidaz (−), DNaz (+), maltozu okside eder."},
{k:"Bakteriyoloji",s:"Gardnerella vaginalis ve bakteriyel vajinozda Amsel ve Nugent kriterleri nelerdir?",c:"Amsel (4'ten 3'ü): homojen ince akıntı, pH >4.5, KOH ile amin (balık) kokusu, mikroskopide clue cell. Nugent skoru: Gram boyamada Lactobacillus (büyük Gram+ basil), Gardnerella/Bacteroides (küçük Gram-değişken basil) ve Mobiluncus (kıvrık basil) morfotipleri sayılır; 0-3 normal, 4-6 ara, 7-10 bakteriyel vajinoz."},
{k:"Bakteriyoloji",s:"Aeromonas ve Plesiomonas'ın laboratuvar özellikleri nelerdir?",c:"Her ikisi de oksidaz (+) Gram negatif basillerdir ve Enterobacterales'ten oksidaz pozitifliği ile ayrılır. Aeromonas hydrophila: tatlı su teması, beta hemolitik, sulu ishal ve yara enfeksiyonu; Plesiomonas shigelloides: deniz ürünleri ile ilişkili gastroenterit. Vibrio'dan farklı olarak NaCl gerektirmezler ve O/129 bileşiğine dirençlidirler."},
{k:"Bakteriyoloji",s:"Yersinia enterocolitica izolasyonunda hangi özel yöntemler kullanılır?",c:"CIN (sefsulodin-irgasan-novobiyosin) agarda 'boğa gözü' koloni; 25-28°C'de üreme; soğukta zenginleştirme (4°C'de PBS'de 2-3 hafta). 25°C'de hareketli, 37°C'de hareketsizdir; üreaz (+). Psödoapandisit tablosu ve reaktif artrit ile ilişkilidir."},
{k:"Bakteriyoloji",s:"Streptococcus pneumoniae'nin virülans faktörleri nelerdir?",c:"Polisakkarit kapsül (ana virülans faktörü, >90 serotip, aşıların hedefi), pnömolizin (kolesterol bağlayan sitolizin), IgA1 proteaz, otolizin (LytA), teikoik asit ve C-polisakkarit (CRP'yi bağlar), yüzey proteini A (PspA, kompleman inhibisyonu)."},
{k:"Bakteriyoloji",s:"Quellung (kapsül şişme) reaksiyonu nedir?",c:"Tip-özgül antikapsüler antiserumun kapsüle bağlanmasıyla kapsülün ışık kırıcılığının artması ve mikroskopide şişmiş gibi görünmesidir. S. pneumoniae serotiplendirmesinde klasik yöntemdir; H. influenzae, K. pneumoniae ve N. meningitidis için de kullanılabilir."},
{k:"Bakteriyoloji",s:"BOS bulguları bakteriyel, viral ve tüberküloz menenjiti nasıl ayırır?",c:"Bakteriyel: nötrofil hakim (>1000/mm3), glukoz çok düşük (BOS/kan <0.4), protein çok yüksek, laktat >3.5 mmol/L. Viral: lenfosit hakim, glukoz normal, protein hafif yüksek. Tüberküloz/fungal: lenfosit hakim, glukoz düşük, protein çok yüksek, ADA yüksek, pıhtı (örümcek ağı) oluşumu."},
{k:"Bakteriyoloji",s:"Sterilizasyon ve dezenfeksiyon arasındaki fark nedir; Spaulding sınıflaması nasıldır?",c:"Sterilizasyon tüm mikroorganizmaları, sporlar dahil yok eder; dezenfeksiyon vejetatif formları azaltır. Spaulding: kritik aletler (steril dokuya girer — cerrahi aletler) sterilizasyon; yarı kritik (mukoza teması — endoskop) yüksek düzey dezenfeksiyon; kritik olmayan (sağlam deri) düşük-orta düzey dezenfeksiyon gerektirir."},
{k:"Bakteriyoloji",s:"Otoklavın etkinliği nasıl kontrol edilir?",c:"Fiziksel (süre, sıcaklık, basınç kayıtları), kimyasal (Bowie-Dick testi, indikatör bantlar, sınıf 5-6 entegratörler) ve biyolojik indikatörler. Biyolojik indikatör altın standarttır: Geobacillus stearothermophilus sporları (buhar, 121°C) ve Bacillus atrophaeus (kuru ısı/etilen oksit) kullanılır."},
/* ---------------- SEROLOJİ ---------------- */
{k:"Seroloji",s:"Prozon ve postzon fenomeni nedir, nasıl önlenir?",c:"Prozon: antikor fazlalığında her antijen bölgesi ayrı antikorla kaplanır, kafes oluşmaz ve reaksiyon yalancı negatif çıkar (Brucella, sifiliz). Postzon: antijen fazlalığında aynı nedenle negatiflik görülür. Önlem: serumun seri dilüsyonlarının çalışılması (yüksek dilüsyonlarda pozitiflik ortaya çıkar)."},
{k:"Seroloji",s:"Presipitasyon ve aglütinasyon reaksiyonları arasındaki temel fark nedir?",c:"Presipitasyonda antijen çözünürdür ve antikorla çöken kafes oluşturur (immündifüzyon, immünelektroforez, nefelometri). Aglütinasyonda antijen partikülerdir (hücre, lateks) ve görünür kümeleşme oluşur. Aglütinasyon daha duyarlıdır çünkü daha az antikorla görünür sonuç verir."},
{k:"Seroloji",s:"Direkt ve indirekt Coombs testleri neyi gösterir?",c:"Direkt Coombs: hastanın eritrositleri üzerinde in vivo bağlanmış IgG veya C3d'yi gösterir (otoimmün hemolitik anemi, yenidoğanın hemolitik hastalığı, ilaç ilişkili hemoliz). İndirekt Coombs: serumdaki serbest, eritrosite bağlanmamış antikorları gösterir (kan uygunluk testi, antikor tarama, Brucella blokan antikorları)."},
{k:"Seroloji",s:"ELISA tipleri nelerdir ve hangi durumda hangisi seçilir?",c:"Direkt (tek antikor, hızlı), indirekt (antijen kaplı kuyucukta hasta antikoru aranır — viral seroloji), sandviç (iki antikor arası antijen — HBsAg, sitokin), kompetitif/blokan (anti-HBc, anti-HBe gibi; sinyal azalması pozitifliktir). Sandviç ELISA yüksek özgüllük, indirekt ELISA yüksek duyarlılık sağlar."},
{k:"Seroloji",s:"Avidite testi nedir, klinikte ne için kullanılır?",c:"IgG'nin antijene bağlanma gücünü ölçer; üre gibi bir denatüran ile yıkama sonrası kalan bağlanma oranıdır. Düşük avidite (<%30-40) son 3-4 ay içinde geçirilmiş primer enfeksiyonu, yüksek avidite (>%60) geçmiş enfeksiyonu gösterir. Gebede Toxoplasma, CMV ve rubella IgM pozitifliğinin yorumunda kritik öneme sahiptir."},
{k:"Seroloji",s:"Sifiliz serolojisinde treponemal ve non-treponemal testlerin farkı nedir?",c:"Non-treponemal (VDRL, RPR): kardiyolipin-lesitin-kolesterol antijenine karşı reagin antikorlarını ölçer; hastalık aktivitesi ve tedavi takibinde kullanılır, titre düşer. Treponemal (TPHA, TPPA, FTA-ABS, EIA/CIA): treponema özgül antikorları saptar, ömür boyu pozitif kalır, tedavi takibinde kullanılmaz."},
{k:"Seroloji",s:"Ters (reverse) sifiliz tarama algoritması nasıl işler?",c:"Önce otomatize treponemal test (EIA/CIA) yapılır. Pozitifse RPR/VDRL çalışılır. Treponemal(+)/RPR(+) → aktif veya tedavi edilmiş sifiliz. Treponemal(+)/RPR(−) → ikinci farklı treponemal test (TPPA); pozitifse geçirilmiş/geç latent sifiliz, negatifse yalancı pozitiflik. Bu algoritma erken ve geç latent olguları klasik algoritmadan daha iyi yakalar."},
{k:"Seroloji",s:"VDRL'de biyolojik yalancı pozitiflik hangi durumlarda görülür?",c:"Akut: gebelik, aşılama, viral enfeksiyonlar (EBV, hepatit, HIV), sıtma, tüberküloz. Kronik (>6 ay): antifosfolipid sendromu, SLE, romatoid artrit, IV ilaç kullanımı, lepra, ileri yaş. Titre genellikle düşüktür (≤1/8) ve treponemal testler negatiftir."},
{k:"Seroloji",s:"Hepatit B serolojik belirteçleri akut enfeksiyonu, iyileşmeyi ve aşı yanıtını nasıl ayırır?",c:"Akut: HBsAg(+), anti-HBc IgM(+), HBeAg(+). Kronik: HBsAg >6 ay (+), anti-HBc IgG(+), anti-HBs(−). İyileşme: anti-HBs(+), anti-HBc IgG(+), HBsAg(−). Aşı yanıtı: yalnız anti-HBs(+) (anti-HBc negatif). Pencere dönemi: HBsAg(−), anti-HBs(−), yalnız anti-HBc IgM(+)."},
{k:"Seroloji",s:"HBV'de 'pencere dönemi' nedir?",c:"HBsAg'nin kaybolduğu ancak anti-HBs'nin henüz saptanabilir düzeye çıkmadığı, haftalar-aylar süren dönemdir. Bu dönemde tek pozitif belirteç anti-HBc IgM'dir; hasta bulaştırıcı olabilir. Bu nedenle anti-HBc taraması kan bankacılığında önemlidir."},
{k:"Seroloji",s:"HIV tanısında 4. kuşak test ve doğrulama algoritması nasıldır?",c:"4. kuşak kombine test p24 antijeni + anti-HIV-1/2 antikorlarını arar, pencere dönemini ~15-20 güne indirir. Reaktif ise HIV-1/HIV-2 antikor ayrım testi yapılır; ayrım testi negatif veya belirsizse HIV-1 RNA (NAAT) çalışılır. Western blot artık algoritmanın standart basamağı değildir."},
{k:"Seroloji",s:"Anti-HCV pozitifliği enfeksiyonu kanıtlar mı?",c:"Hayır. Anti-HCV geçirilmiş veya süregelen enfeksiyonu ayırt etmez ve spontan iyileşenlerde de pozitif kalır. Aktif enfeksiyon için HCV RNA (kalitatif/kantitatif NAAT) veya HCV kor antijeni gerekir. İmmünsüprese hastalarda antikor yanıtı olmayabilir, doğrudan RNA bakılmalıdır."},
{k:"Seroloji",s:"EBV serolojisinde VCA IgM, VCA IgG, EBNA ve anti-EA nasıl yorumlanır?",c:"Akut enfeksiyon: VCA IgM(+), VCA IgG(+), EBNA(−). Geçirilmiş: VCA IgG(+), EBNA(+), VCA IgM(−). Duyarlı (hiç geçirmemiş): hepsi negatif. EBNA antikorları 6-8 hafta sonra ortaya çıkar, bu nedenle EBNA pozitifliği akut enfeksiyonu dışlar. Anti-EA reaktivasyon veya aktif enfeksiyonu destekler."},
{k:"Seroloji",s:"Paul-Bunnell (heterofil antikor) testi nedir ve sınırlılıkları nelerdir?",c:"EBV enfeksiyöz mononükleozunda oluşan, koyun/at eritrositlerini aglütine eden IgM sınıfı heterofil antikorları saptar (Monospot). Kobay böbreği ile absorbe edilmez, sığır eritrositi ile absorbe edilir — bu serum hastalığından ayırır. 4 yaş altı çocuklarda ve olguların ~%10'unda negatiftir; özgül EBV serolojisi gerekir."},
{k:"Seroloji",s:"TORCH taraması nedir ve yorumunda nelere dikkat edilir?",c:"Toxoplasma, Others (sifiliz, HBV, parvovirüs B19, VZV, HIV), Rubella, CMV, HSV. Konjenital enfeksiyon şüphesinde kullanılır. Yorumda anne IgG'sinin plasentadan geçtiği (bebekte 6-12 ay pozitif kalabilir) unutulmamalıdır; bebekte IgM veya IgA pozitifliği ya da doğrudan etken saptanması (PCR, kültür) tanısaldır."},
{k:"Seroloji",s:"Rubella IgG pozitifliği gebede nasıl yorumlanır?",c:"Tek başına IgG pozitifliği bağışıklığı gösterir ve gebelik için güvencedir (≥10 IU/mL). IgM pozitifliği akut enfeksiyon, yalancı pozitiflik, reenfeksiyon veya uzun süren IgM persistansı olabilir; avidite testi ve çift serumda IgG serokonversiyonu ile doğrulanmalıdır. Aşı canlı olduğundan gebelikte yapılmaz."},
{k:"Seroloji",s:"ASO titresi neyi gösterir ve hangi durumlarda yanıltıcıdır?",c:"S. pyogenes'in streptolizin O'suna karşı antikorları gösterir; geçirilmiş streptokok enfeksiyonunu ve akut romatizmal ateş tanısında Jones minör kriterini destekler. Deri enfeksiyonlarında (impetigo) kolesterol streptolizin O'yu nötralize ettiği için ASO düşük kalır; anti-DNaz B daha değerlidir. Tek yüksek değer aktif enfeksiyonu kanıtlamaz, titre seyri önemlidir."},
{k:"Seroloji",s:"Weil-Felix, Widal ve Wright testlerinin ortak zayıflığı nedir?",c:"Üçü de aglütinasyon temelli, özgüllüğü sınırlı testlerdir; endemik bölgelerde geçmiş enfeksiyon veya aşıya bağlı bazal titreler nedeniyle tek serumda yorum güçtür. Hepsinde çift serumda (2-3 hafta arayla) ≥4 kat titre artışı aranmalı ve klinikle birlikte değerlendirilmelidir."},
{k:"Seroloji",s:"Kompleman fiksasyon testinin prensibi nedir?",c:"İki aşamalıdır: 1) Hasta serumu + antijen + standart kompleman inkübe edilir; antikor varsa kompleman tüketilir. 2) İndikatör sistem (koyun eritrositi + hemolizin) eklenir. Hemoliz yoksa kompleman tüketilmiştir → test pozitif; hemoliz varsa kompleman serbesttir → negatif. Serum önce 56°C'de 30 dk inaktive edilmelidir."},
{k:"Seroloji",s:"Serumun 56°C'de 30 dakika inaktivasyonu neden yapılır?",c:"Hastanın kendi kompleman sistemini (özellikle ısıya duyarlı C1 ve C2) inaktive etmek ve non-spesifik inhibitörleri gidermek için; kompleman fiksasyon, nötralizasyon ve bazı aglütinasyon testlerinde yalancı sonuçları önler. Aşırı ısıtma antikorları da denatüre edebilir."},
{k:"Seroloji",s:"Nefelometri ve türbidimetri farkı nedir?",c:"Türbidimetri geçen ışığın azalmasını ölçer, nefelometri ise partiküllerden saçılan ışığı (genellikle 30-90°) ölçer. Nefelometri düşük konsantrasyonlarda daha duyarlıdır. İmmünglobulinler, kompleman bileşenleri, CRP ve romatoid faktör ölçümünde kullanılır."},
{k:"Seroloji",s:"Western blot (immünoblot) yöntemi nasıl çalışır?",c:"Antijen karışımı SDS-PAGE ile moleküler ağırlığa göre ayrılır, nitroselüloz/PVDF membrana aktarılır, hasta serumu ile inkübe edilir ve enzim işaretli antiglobulin + substrat ile bantlar görünür hale getirilir. Belirli bantların varlığı ve sayısı yorum kriterlerini oluşturur (Lyme, HIV-2 doğrulama, anti-HTLV)."},
{k:"Seroloji",s:"Line immunoassay (LIA) ile Western blot arasındaki fark nedir?",c:"Western blot'ta antijenler jelde elektroforezle ayrılıp aktarılır; LIA'da ise saflaştırılmış ya da rekombinant antijenler membrana önceden çizgiler halinde püskürtülür. LIA standardizasyonu daha iyi, yorumu daha nettir ve seçilmiş epitoplarla özgüllüğü artırılabilir (HCV RIBA, anti-ENA profilleri)."},
{k:"Seroloji",s:"Duyarlılık, özgüllük, PPD ve NPD kavramları nasıl tanımlanır?",c:"Duyarlılık = GP/(GP+YN): hastaları yakalama gücü. Özgüllük = GN/(GN+YP): sağlamları dışlama gücü. Pozitif prediktif değer = GP/(GP+YP), negatif prediktif değer = GN/(GN+YN). PPD ve NPD prevalansa bağımlıdır: prevalans düştükçe PPD düşer, bu nedenle düşük prevalanslı toplumlarda tarama testlerinin doğrulanması şarttır."},
{k:"Seroloji",s:"Gri bölge (equivocal) sonuçlarda ne yapılmalıdır?",c:"Test tekrarlanmalı, 2-3 hafta sonra ikinci serum örneği alınıp eş zamanlı çalışılmalı, mümkünse farklı prensipte bir doğrulama testi veya doğrudan etken saptama yöntemi (PCR, antijen, kültür) uygulanmalıdır. Klinik ve epidemiyolojik veriler olmadan gri bölge sonucu tek başına raporlanıp yorumlanmamalıdır."},
{k:"Seroloji",s:"Romatoid faktör serolojik testlerde nasıl bir sorun yaratır?",c:"RF, IgG'nin Fc bölgesine bağlanan (çoğunlukla IgM sınıfı) bir otoantikordur. IgM yakalama olmayan indirekt IgM testlerinde, antijene bağlı spesifik IgG'ye tutunarak yalancı IgM pozitifliği yaratır. Önlem: IgG absorbanı (RF-absorbent) kullanmak veya µ-capture (IgM yakalama) formatı seçmek."},
{k:"Seroloji",s:"Hook (kanca) etkisi nedir?",c:"Sandviç immünoassaylerde analit konsantrasyonunun aşırı yüksek olması durumunda yakalama ve işaret antikorlarının ayrı ayrı doygunlaşıp sandviç oluşumunun engellenmesi ve yalancı düşük/negatif sonuç alınmasıdır. HBsAg, kriptokok antijeni, beta-hCG ölçümlerinde görülür; şüphede örnek seyreltilerek tekrar çalışılır."},
{k:"Seroloji",s:"Kriptokok antijen testi nasıl çalışır ve hangi örnekte kullanılır?",c:"Kapsüler glukuronoksilomannan antijenini lateks aglütinasyon, EIA veya lateral flow assay (LFA) ile saptar. Serum ve BOS'ta kullanılır; duyarlılık ve özgüllüğü >%90'dır. LFA hızlı, ucuz ve saha koşullarına uygundur. Yalancı pozitiflik: romatoid faktör, Trichosporon, bazı malignite ve dezenfektan kalıntıları."},
{k:"Seroloji",s:"Galaktomannan ve beta-D-glukan testleri hangi mantar enfeksiyonlarında kullanılır?",c:"Galaktomannan: Aspergillus hücre duvarı antijeni; serum ve BAL'da invaziv aspergilloz tanısında (BAL'da daha duyarlı). Beta-D-glukan: panfungal belirteç; Candida, Aspergillus, Pneumocystis ve Fusarium'da pozitif, Cryptococcus ve Mucorales'te negatiftir. İkisi de tanıyı destekler, tek başına tanı koydurmaz."},
{k:"Seroloji",s:"Galaktomannan testinde yalancı pozitiflik nedenleri nelerdir?",c:"Piperasilin-tazobaktam ve amoksisilin-klavulanat (eski formülasyonlar), PLASMA-LYTE gibi sıvılar, diğer mantarlar (Histoplasma, Fusarium, Penicillium/Talaromyces), yoğun mukozit ve beslenme ürünlerinden bağırsak translokasyonu, yenidoğan dönemi. Antifungal profilaksi altında ise yalancı negatiflik artar."},
{k:"Seroloji",s:"Prokalsitonin ve CRP'nin mikrobiyolojik yorumdaki yeri nedir?",c:"Prokalsitonin bakteriyel sistemik enfeksiyonda hızla (2-4 saatte) yükselir, viral enfeksiyonlarda IFN-γ etkisiyle baskılanır; antibiyotik kesilme kararında rehberlik eder. CRP daha geç yükselir ve daha az özgüldür. İkisi de kültürün yerini tutmaz; ampirik tedaviyi kısaltmak için yardımcı belirteçlerdir."},
{k:"Seroloji",s:"Kantitatif serolojide 'titre' nedir ve 4 kat artış neden aranır?",c:"Titre, pozitif reaksiyon veren en yüksek serum dilüsyonunun tersidir (1/160 gibi). İki kat dilüsyon serilerinde bir basamaklık fark yöntem içi değişkenlikle açıklanabilir; iki basamak (4 kat) artış istatistiksel olarak anlamlı kabul edilir ve akut enfeksiyonu gösterir. Akut ve konvalesan serumlar aynı çalışmada, aynı seride test edilmelidir."},
{k:"Seroloji",s:"IgM pozitifliğinin akut enfeksiyon dışındaki nedenleri nelerdir?",c:"Uzun süreli IgM persistansı (Toxoplasma'da yıllarca), reenfeksiyon/reaktivasyon, poliklonal aktivasyon (EBV, CMV çapraz uyarımı), romatoid faktör ve otoantikorlar, gebelik, yakın zamanda aşılama, heterofil antikorlar. Bu nedenle IgM tek başına tanı koydurmaz, avidite ve çift serum ile desteklenmelidir."},
{k:"Seroloji",s:"Nötralizasyon testi nedir ve hangi amaçlarla kullanılır?",c:"Hasta serumundaki antikorların virüsün hücreye girişini/sitopatik etkisini engelleme yeteneğini ölçer (plak redüksiyon nötralizasyon testi - PRNT altın standart). Koruyucu antikor düzeyinin belirlenmesinde (kızamık, kuduz, kabakulak, arbovirüsler) ve flavivirüs serolojisindeki çapraz reaksiyonların çözülmesinde kullanılır. Canlı virüs gerektirir, yavaş ve yüksek biyogüvenlik ister."},
{k:"Seroloji",s:"Hemaglütinasyon inhibisyon (HI) testi nasıl çalışır?",c:"Influenza, kızamık, kabakulak, rubella gibi hemaglütinin taşıyan virüslerin eritrositleri aglütine etmesi, hasta serumundaki özgül antikorlarca engellenir. Aglütinasyonu inhibe eden en yüksek dilüsyon titredir. Serum önce non-spesifik inhibitörler için reseptör yıkıcı enzim (RDE) ile muamele edilir. Influenza aşı yanıtı değerlendirmesinde HI ≥1/40 koruyucu kabul edilir."},
{k:"Seroloji",s:"Kompleman sisteminin üç aktivasyon yolu nasıl ayrılır ve hangi testlerle ölçülür?",c:"Klasik yol (antijen-antikor kompleksi, C1q), lektin yolu (MBL-mannoz), alternatif yol (spontan C3b, mikrobiyal yüzey). Hepsi C3 ve C5 konvertazda birleşir. CH50 klasik yolun, AH50 alternatif yolun bütünlüğünü ölçer; ikisi de düşükse ortak yolda (C3-C9) defekt vardır. Terminal yol eksikliği tekrarlayan Neisseria enfeksiyonlarına yatkınlık yapar."},
{k:"Seroloji",s:"Quantiferon (IGRA) testi nasıl çalışır, tüberkülin deri testinden farkı nedir?",c:"Hastanın T hücreleri M. tuberculosis'e özgü ESAT-6, CFP-10 (ve TB7.7) antijenleri ile uyarılır; salınan IFN-γ ELISA (QFT) veya ELISPOT (T-SPOT.TB) ile ölçülür. BCG aşısı ve çoğu atipik mikobakteriden etkilenmez, tek ziyaret gerektirir. Ancak aktif ile latent tüberkülozu ayırt edemez ve immünsüpresyonda belirsiz sonuç verebilir."},
{k:"Seroloji",s:"Kist hidatik (Ekinokokkoz) serolojisinde hangi testler kullanılır?",c:"Tarama: indirekt hemaglütinasyon (IHA) veya ELISA (Echinococcus granulosus antijen B). Doğrulama: immünoblot (8 kDa/12 kDa bantları) veya Arc-5 immünelektroforez. Duyarlılık kist yerleşimine göre değişir (karaciğerde yüksek, akciğer ve beyinde düşük); kalsifiye/inaktif kistlerde negatif olabilir. Tedavi izleminde titre düşüşü değerlidir."},
{k:"Seroloji",s:"Toxoplasma serolojisinde gebede sonuçlar nasıl yorumlanır?",c:"IgG(−)/IgM(−): duyarlı, korunma önerilir ve tekrar taranır. IgG(+)/IgM(−): geçmiş enfeksiyon, bağışık. IgG(−)/IgM(+): çok erken enfeksiyon ya da yalancı pozitiflik; 2-3 hafta sonra tekrar. IgG(+)/IgM(+): avidite testi yapılır — yüksek avidite ilk 12-16 haftada enfeksiyonu dışlar, düşük avidite yakın enfeksiyonu düşündürür; fetal tanı için amniyon sıvısında PCR."},
{k:"Seroloji",s:"Otoimmün serolojide ANA paterni ile hastalık ilişkisi nasıldır?",c:"Homojen: anti-dsDNA/histon, SLE ve ilaç ilişkili lupus. Benekli: anti-Sm, RNP, SSA/SSB — MCTD, Sjögren, SLE. Nükleolar: anti-Scl-70/fibrillarin — sistemik skleroz. Sentromer: limitli skleroderma (CREST). Periferik/rim: anti-dsDNA, SLE. Patern ipucudur; kesin tanı özgül antikor testleriyle (ENA paneli, anti-dsDNA) konur."},
{k:"Seroloji",s:"Soğuk aglütininler nedir ve hangi enfeksiyonlarla ilişkilidir?",c:"4°C'de eritrositleri aglütine eden, 37°C'de ayrışan IgM antikorlarıdır (çoğunlukla I/i antijenine karşı). Mycoplasma pneumoniae (anti-I), EBV (anti-i), CMV ve bazı lenfoproliferatif hastalıklarda görülür. Örnek 37°C'de taşınmazsa yalancı sonuçlar ve otomatik hemogram hataları oluşur."},
{k:"Seroloji",s:"İmmünkromatografik (lateral flow) hızlı testlerin avantaj ve sınırlılıkları nelerdir?",c:"Avantaj: dakikalar içinde sonuç, cihaz gerektirmez, hasta başı kullanım, saha ve acil koşullarına uygun. Sınırlılık: kalitatif, duyarlılığı laboratuvar testlerinden düşük olabilir, subjektif okuma, düşük analit düzeylerinde yalancı negatiflik, hook etkisi. Negatif sonuç klinik şüphede doğrulanmalıdır."},
{k:"Seroloji",s:"Kemilüminesans immünoassay (CLIA) ELISA'ya göre hangi üstünlükleri sağlar?",c:"Enzim-substrat kolorimetrisi yerine ışık yayan etiket (akridinyum ester, ruthenium) kullanılır; dinamik aralık daha geniş, duyarlılık daha yüksek, sonuç süresi daha kısa ve tam otomasyona uygundur. Rastgele erişimli cihazlarda tek örnekten çoklu parametre çalışılabilir."},
{k:"Seroloji",s:"Serolojik testlerde çapraz reaksiyon örnekleri nelerdir?",c:"Flavivirüsler arası (Dengue-Zika-Batı Nil), Brucella ile Yersinia enterocolitica O:9, Francisella ve Vibrio cholerae; sifiliz ile diğer treponemal hastalıklar (yaws, pinta); Legionella ile Campylobacter; Entamoeba histolytica ile E. dispar; Leishmania ile Trypanosoma cruzi. Çözüm: nötralizasyon, özgül rekombinant antijenli testler veya moleküler yöntemler."},
{k:"Seroloji",s:"Serum, plazma ve tam kan örneklerinin serolojide kullanım farkları nelerdir?",c:"Serum çoğu immünoassayin referans matriksidir (fibrinojen yoktur, bulanıklık azdır). Plazma antikoagülan (EDTA, heparin, sitrat) içerir; heparin bazı testlerde girişim yapar, sitrat dilüsyon etkisi yaratır. Hemoliz, lipemi ve ikter optik ölçümlerde girişim yapar. Kit prospektüsünde onaylanmamış matriks kullanılmamalıdır."},
{k:"Seroloji",s:"Aşı ile doğal enfeksiyonun serolojik olarak ayrımı nasıl yapılır?",c:"Enfeksiyona özgü ama aşıda bulunmayan antijenlere karşı antikorlar aranır: HBV'de anti-HBc (aşıda yoktur), tetanoz/difteride toksoid dışı antijenler, SARS-CoV-2'de spike aşılarına karşı nükleokapsid antikoru. Ayrıca DIVA stratejileri (Differentiating Infected from Vaccinated Animals) veteriner serolojisinde bu ilkeye dayanır."},
{k:"Seroloji",s:"İmmünfloresan ve enzim immünoassay arasındaki temel farklar nelerdir?",c:"İFA'da işaret floroforedir ve sonuç floresan mikroskobuyla morfolojik patern olarak okunur (subjektif, deneyim gerektirir, patern bilgisi verir). EIA'da işaret enzimdir, sonuç spektrofotometrik olarak sayısal okunur (objektif, otomasyona uygun, ama morfolojik bilgi vermez)."},
{k:"Seroloji",s:"Antijen tarama testlerinde 'pencere dönemi' neden önemlidir?",c:"Enfeksiyondan sonra antijenin veya antikorun saptanabilir düzeye çıkmasına kadar geçen süredir; bu dönemde test negatif olsa da kişi bulaştırıcıdır. Kan bankacılığında NAAT eklenmesi HIV'de pencereyi ~9 güne, HCV'de ~7 güne indirmiştir. Yüksek riskli temas sonrası negatif test mutlaka tekrarlanmalıdır."},
{k:"Seroloji",s:"Serolojik testlerde iç ve dış kalite kontrolü nasıl yürütülür?",c:"İç kalite kontrol: her çalışmada pozitif, zayıf pozitif ve negatif kontrollerin çalışılması, Levey-Jennings grafikleri ve Westgard kurallarıyla izlenmesi, kit lot değişiminde paralel çalışma. Dış kalite değerlendirme: bağımsız kuruluşların gönderdiği bilinmeyen paneller ile laboratuvarlar arası karşılaştırma (EQA/yeterlilik testi)."},
{k:"Seroloji",s:"Anti-HBs düzeyinin klinik yorumu nasıldır?",c:"≥10 mIU/mL koruyucu kabul edilir. Aşı sonrası ölçüm 1-2 ay sonra yapılır. <10 mIU/mL ise yanıtsızlık; tekrar aşı serisi uygulanır, hâlâ yanıtsızsa HBsAg bakılarak kronik taşıyıcılık dışlanır. İmmünsüprese ve diyaliz hastalarında daha yüksek doz ve düzenli titre izlemi gerekir."},
{k:"Seroloji",s:"Kızamık salgın araştırmasında serolojik yaklaşım nasıl olmalıdır?",c:"Döküntünün ilk 3 gününde IgM negatif olabilir, 3-28 gün arasında en yüksek duyarlılık vardır; negatifse 72 saat sonra tekrarlanır. Destekleyici: çift serumda IgG serokonversiyonu veya 4 kat artış. Doğrulama ve genotipleme için idrar/nazofarengeal örnekte RT-PCR gerekir; aşı ilişkili döküntü ile vahşi tip ayrımı genotip ile yapılır."},
{k:"Seroloji",s:"Serolojik test sonucu ile klinik uyuşmadığında izlenecek yol nedir?",c:"Preanalitik hataları (örnek karışması, yanlış tüp, yetersiz/gecikmiş örnek) kontrol et, testi aynı ve farklı bir yöntemle tekrarla, girişim yapan faktörleri (RF, heterofil antikor, hook etkisi, biotin) değerlendir, yeni bir örnek iste ve mümkünse doğrudan etken saptama yöntemine (PCR, kültür, antijen) geç. Sonuç klinikle birlikte, gerekirse klinisyenle görüşülerek raporlanır."},
{k:"Seroloji",s:"Biotin girişimi immünoassaylerde nasıl bir hata yaratır?",c:"Streptavidin-biotin temelli sistemlerde hastanın yüksek doz biotin (B7) kullanımı, reaktifteki biotinli antikorların streptavidinle bağlanmasını rekabetçi biçimde engeller: sandviç testlerde yalancı düşük/negatif, kompetitif testlerde yalancı yüksek sonuç doğar. Önlem: test öncesi 8-72 saat biotin kesilmesi ve şüpheli sonuçların farklı platformda doğrulanması."},
/* ---------------- MİKOLOJİ ---------------- */
{k:"Mikoloji",s:"KOH preparatı nasıl hazırlanır ve neyi gösterir?",c:"Örnek (deri kazıntısı, tırnak, kıl) lam üzerine konur, %10-20 KOH (tırnak için %40 veya DMSO'lu) damlatılır, lamel kapatılıp 10-30 dakika bekletilir veya hafif ısıtılır. Keratin eritilir, mantar hücre duvarı dayanıklı olduğundan hifler ve sporlar görünür hale gelir. Kalkoflor beyazı eklenerek floresan mikroskopla duyarlılık artırılır."},
{k:"Mikoloji",s:"Sabouraud dekstroz agarın özellikleri ve katkıları nelerdir?",c:"Yüksek glukoz (%2-4) ve düşük pH (5.6) bakteri üremesini baskılar. Kloramfenikol/gentamisin bakterileri, sikloheksimid (aktidion) saprofit küfleri baskılar. Dikkat: sikloheksimid Cryptococcus, Aspergillus, Candida krusei, Mucorales ve Trichosporon'u da inhibe eder; şüpheli örnek hem katkılı hem katkısız besiyerine ekilmelidir."},
{k:"Mikoloji",s:"Dimorfik mantarlar hangileridir ve hangi formu hangi sıcaklıkta gösterirler?",c:"Histoplasma capsulatum, Blastomyces dermatitidis, Coccidioides immitis, Paracoccidioides brasiliensis, Sporothrix schenckii, Talaromyces marneffei. 25°C'de (doğada/kültürde) küf, 37°C'de (dokuda) maya formundadır. Coccidioides istisnadır: dokuda maya değil, endosporlarla dolu sferül oluşturur."},
{k:"Mikoloji",s:"Candida albicans'ı diğer Candida türlerinden ayıran hızlı testler nelerdir?",c:"Germ tüp (çim filizi) testi: serumda 37°C'de 2-3 saat inkübasyonla, blastokonidyumda daralma olmadan çıkan gerçek hif uzantısı. Mısır unlu agarda (Tween 80) kalın duvarlı terminal klamidospor oluşumu. CHROMagar Candida'da yeşil koloni. Doğrulama MALDI-TOF veya ID32C gibi ticari kitlerle yapılır."},
{k:"Mikoloji",s:"CHROMagar Candida'da renkler hangi türleri düşündürür?",c:"Yeşil: C. albicans (ve C. dubliniensis, koyu yeşil). Mavi-metalik: C. tropicalis. Pembe-kaba/tüylü koloni: C. krusei (Pichia kudriavzevii). Beyaz-lila: C. glabrata (Nakaseomyces glabratus) ve diğerleri. Renkler ön tanı sağlar, kesin tanımlama için ek yöntem gerekir."},
{k:"Mikoloji",s:"Candida auris neden özel bir tehdittir ve nasıl tanımlanır?",c:"Çoklu antifungal direnci (özellikle flukonazol, bazen amfoterisin B ve ekinokandin), hastane yüzeylerinde uzun süre kalıcılık ve salgın yapma potansiyeli vardır. Rutin biyokimyasal sistemlerde C. haemulonii, Rhodotorula veya Saccharomyces olarak yanlış tanımlanabilir; doğru tanı güncel veri tabanlı MALDI-TOF veya dizi analizi ile konur. Temas izolasyonu ve sporisidal dezenfeksiyon gerekir."},
{k:"Mikoloji",s:"Cryptococcus neoformans tanısında kullanılan yöntemler nelerdir?",c:"Çini mürekkebi/nigrosin negatif boyama (BOS'ta kapsüllü tomurcuklanan maya; duyarlılık ~%50-80), kriptokok antijen testi (lateks/EIA/LFA, >%90 duyarlı), kültür (Sabouraud, birkaç gün), Niger seed (kuşyemi) agarında melanin üretimiyle kahverengi koloni, üreaz (+), fenol oksidaz (+). Histopatolojide musikarmin ve Fontana-Masson pozitiftir."},
{k:"Mikoloji",s:"C. neoformans ile C. gattii arasındaki fark nedir?",c:"C. neoformans immünsüpresiflerde (özellikle HIV, CD4<100) menenjit yapar, güvercin dışkısı ile ilişkilidir. C. gattii bağışıklığı normal kişilerde de hastalık yapar, okaliptüs ağaçları ile ilişkilidir, akciğer ve beyinde kriptokokkom oluşturma eğilimi yüksektir. CGB (kanavanin-glisin-bromtimol mavisi) agarında C. gattii besiyerini maviye çevirir."},
{k:"Mikoloji",s:"Aspergillus türleri mikroskobik olarak nasıl ayrılır?",c:"A. fumigatus: kısa, düzgün konidiyofor, tek sıralı (uniseriate) fialidler yalnız üst yarıda, mavi-yeşil koloni, 45-50°C'de ürer. A. flavus: çift sıralı (biseriate) ve tüm yüzeyi kaplayan fialidler, sarı-yeşil koloni, aflatoksin. A. niger: siyah, radyal (tüm vezikülü saran) biseriate yapı. A. terreus: tarçın rengi, amfoterisin B'ye dirençli."},
{k:"Mikoloji",s:"Mukormikoz etkenlerinin histopatolojik ve kültürel özellikleri nelerdir?",c:"Geniş (5-20 µm), septasız/az septalı, düzensiz dallanan (genellikle 90°) hifler; damar invazyonu ve nekroz belirgindir. Kültürde hızlı üreyen, tüp ağzını dolduran pamuksu 'ekmek küfü' (Rhizopus, Mucor, Lichtheimia). Rhizopus'ta rizoidler sporangiyoforun tam dibinde, Lichtheimia'da stolonlar arasındadır. Beta-D-glukan ve galaktomannan negatiftir."},
{k:"Mikoloji",s:"Aspergillus ile Mucorales hiflerini doku kesitinde ne ayırır?",c:"Aspergillus: 3-6 µm, düzenli septalı, dar açılı (45°, 'geyik boynuzu') dikotom dallanma. Mucorales: 5-20 µm, geniş, şerit benzeri, septasız (senositik), düzensiz ve dik açılı (90°) dallanma, sıklıkla katlanmış görünüm. GMS ve PAS boyaları her ikisini de gösterir; ayrım morfolojiyle yapılır ve tedaviyi değiştirir (vorikonazol vs. amfoterisin B/isavukonazol)."},
{k:"Mikoloji",s:"Dermatofitlerin üç cinsi ve makrokonidyum özellikleri nelerdir?",c:"Trichophyton: ince duvarlı, silindirik, az sayıda makrokonidyum; bol mikrokonidyum. Microsporum: kalın, pürtüklü (verrüköz) duvarlı, iğ şeklinde makrokonidyum. Epidermophyton: kalın duvarlı, düzgün, kulüp şeklinde, demetler halinde makrokonidyum; mikrokonidyum yoktur ve kılı tutmaz."},
{k:"Mikoloji",s:"Dermatofit Test Medium (DTM) nasıl çalışır?",c:"İçindeki fenol kırmızısı indikatörü ile dermatofitlerin alkali metabolitleri besiyerini 3-7 gün içinde kırmızıya çevirir; saprofit küfler geç veya hiç renk değiştirmez. Antibiyotik ve sikloheksimid içerir. Rengin geç dönemde saprofitlerle de değişebilmesi nedeniyle erken okuma önemlidir ve tür tanımlaması için SDA'ya pasaj gerekir."},
{k:"Mikoloji",s:"Wood ışığı hangi mantar enfeksiyonlarında hangi rengi verir?",c:"Microsporum canis/audouinii tinea capitis: parlak yeşil-mavi. Malassezia (pitiriyazis versikolor): sarı-altın/bakır. Eritrazma (Corynebacterium minutissimum, mantar değil): mercan kırmızısı. Trichophyton tonsurans floresan vermez — negatif sonuç tinea capitis'i dışlamaz."},
{k:"Mikoloji",s:"Malassezia furfur'un kültür özelliği nedir?",c:"Lipofilik bir mayadır; besiyerine zeytinyağı veya Tween (Dixon, Leeming-Notman besiyeri) eklenmeden Sabouraud'da üremez (M. pachydermatis istisnadır). Mikroskopide 'spagetti ve köfte' görünümü (kısa hifler + küme yapan yuvarlak mayalar) tanısaldır. Lipid infüzyonu alan yenidoğanlarda fungemi yapabilir."},
{k:"Mikoloji",s:"Pneumocystis jirovecii tanısında hangi boyalar ve örnekler kullanılır?",c:"İndüklenmiş balgam veya BAL örneğinde GMS (gümüş), toluidin mavisi ve kalkoflor beyazı kist duvarını boyar; Giemsa/Diff-Quik trofozoit ve intrakistik cisimleri gösterir. DFA daha duyarlıdır; PCR en duyarlı yöntemdir ancak kolonizasyonu da yakalar. Beta-D-glukan destekleyicidir. Kültürde üretilemez."},
{k:"Mikoloji",s:"Histoplasma capsulatum'un mikroskobik ve klinik özellikleri nelerdir?",c:"25°C'de tüberkülat (dikenli) makrokonidyumlar ve küçük mikrokonidyumlar; 37°C'de makrofaj içinde küçük ovoid maya. Kuş/yarasa dışkısıyla zenginleşmiş toprak (mağara, kümes) ile ilişkilidir. Tanıda idrar/serum Histoplasma antijeni hızlı ve duyarlıdır; kemik iliği ve kan kültürü (lizis-sentrifügasyon) yaygın hastalıkta değerlidir."},
{k:"Mikoloji",s:"Sporotrikoz nasıl bulaşır ve nasıl tanınır?",c:"Sporothrix schenckii kompleksi dikenli bitki, gül, yosun (sphagnum) ile travmatik inokülasyonla girer ('bahçıvan hastalığı'); lenfatik yol boyunca nodüler lezyonlar yapar. Kültürde 25°C'de 'papatya/çiçek demeti' şeklinde konidyum dizilimi; dokuda nadir görülen sigar biçimli maya ve asteroid cisimler. Tedavi itrakonazol, ağırda amfoterisin B."},
{k:"Mikoloji",s:"Fusarium enfeksiyonlarının ayırt edici özellikleri nelerdir?",c:"Muz/kayık şeklinde, çok septalı makrokonidyumlar ve mikrokonidyumlar; hızlı üreyen pembe-mor koloni. Nötropenik hastalarda anjiyoinvaziv hastalık yapar ve Aspergillus'tan farklı olarak sık kan kültürü pozitifliği ve deri lezyonları görülür. Birçok antifungale doğal dirençlidir; vorikonazol veya yüksek doz lipid amfoterisin B kullanılır. Kontakt lensle keratit yapar."},
{k:"Mikoloji",s:"Scedosporium/Lomentospora enfeksiyonlarının önemi nedir?",c:"S. apiospermum boğulma olaylarından sonra beyin apsesi yapabilir; L. prolificans neredeyse tüm antifungallere dirençlidir ve mortalitesi çok yüksektir. Mikroskopide tek tek, ovoid, annelidik konidyumlar. Aspergillus ile karışabilir; doğru tanı tedaviyi tamamen değiştirdiği için tür düzeyinde tanımlama şarttır."},
{k:"Mikoloji",s:"Antifungal duyarlılık testinde hangi referans yöntemler kullanılır?",c:"CLSI M27 (mayalar), M38 (küfler) ve EUCAST E.Def 7.4/9.4 broth mikrodilüsyon yöntemleri referanstır. Klinik uygulamada gradyan strip (Etest), kolorimetrik ticari paneller ve otomatize sistemler kullanılır. Okuma: azollerde ve ekinokandinlerde kısmi inhibisyon (%50), amfoterisin B'de tam inhibisyon (%100) esas alınır."},
{k:"Mikoloji",s:"Antifungal ilaçların etki mekanizmaları nelerdir?",c:"Poliyenler (amfoterisin B, nistatin): ergosterole bağlanıp por açar. Azoller: lanosterol 14-α-demetilazı (CYP51/ERG11) inhibe eder. Ekinokandinler (kaspofungin, anidulafungin): 1,3-β-D-glukan sentazı inhibe eder (hücre duvarı). Flusitozin: 5-FU'ya dönüşüp RNA/DNA sentezini bozar. Terbinafin: skualen epoksidazı inhibe eder. Griseofulvin: mikrotübül fonksiyonunu bozar."},
{k:"Mikoloji",s:"Hangi mantarlarda hangi antifungallere doğal direnç vardır?",c:"C. krusei: flukonazole doğal dirençli. C. glabrata: azollere düşük duyarlı/direnç geliştirir. C. parapsilosis: ekinokandinlere MİK'i yüksek (FKS1 doğal polimorfizmi). C. lusitaniae: amfoterisin B direnci. A. terreus: amfoterisin B direnci. Mucorales: vorikonazol ve ekinokandinlere dirençli. Cryptococcus: ekinokandinlere dirençli."},
{k:"Mikoloji",s:"Mantar hücre duvarının bileşenleri ve tanıdaki karşılıkları nelerdir?",c:"Kitin, 1,3-β-D-glukan, mannoprotein ve ergosterol içeren membran. Beta-D-glukan panfungal serum belirtecidir; galaktomannan Aspergillus'a, mannan/anti-mannan Candida'ya özgüdür. Kalkoflor beyazı ve kitin boyaları duvara bağlanarak mikroskobik tanıda kullanılır. Ergosterol poliyen ve azollerin hedefidir."},
{k:"Mikoloji",s:"Laktofenol pamuk mavisi preparatı ne için kullanılır?",c:"Küf kültürlerinin mikroskobik incelemesinde kullanılır: laktik asit yapıyı korur, fenol mikroorganizmaları öldürür, pamuk mavisi kitini boyar, gliserol kurumayı engeller. Selobant (şeffaf bant) veya iğne ile alınan örnekten hazırlanır; sporlanma yapısının bozulmaması için bant yöntemi tercih edilir."},
{k:"Mikoloji",s:"Slayt (lam) kültürü tekniği nedir?",c:"Steril lam üzerine küçük bir agar bloğu konur, kenarlarına mantar ekilir, üzerine lamel kapatılıp nemli ortamda inkübe edilir. Konidyum ve konidiyoforların doğal dizilimi bozulmadan, yerinde incelenebilir. Özellikle dermatofit ve Aspergillus/Penicillium ayrımında değerlidir; dimorfik ve yüksek riskli mantarlarda güvenlik nedeniyle uygulanmaz."},
{k:"Mikoloji",s:"Doku örneklerinde mantarları göstermek için hangi histokimyasal boyalar kullanılır?",c:"GMS (Gomori metenamin gümüş): en duyarlı, mantar duvarı siyah. PAS: polisakkaritleri pembe-magenta boyar. Kalkoflor beyazı: floresan. Musikarmin ve Fontana-Masson: Cryptococcus kapsülü/melanini. Giemsa: Histoplasma ve Pneumocystis intraselüler formları. H&E tek başına yetersiz kalabilir."},
{k:"Mikoloji",s:"İnvaziv fungal enfeksiyonların EORTC/MSG tanı kategorileri nelerdir?",c:"Kanıtlanmış (proven): steril bölgeden histopatoloji veya kültür ile etken gösterimi. Yüksek olasılıklı (probable): konak faktörü (nötropeni, transplant, steroid) + klinik/radyolojik bulgu (halo işareti, hava hilali) + mikolojik kanıt (galaktomannan, BDG, BAL kültürü). Olası (possible): konak faktörü + klinik bulgu var, mikolojik kanıt yok."},
{k:"Mikoloji",s:"Onikomikoz tanısında örnek nasıl alınmalıdır?",c:"Tırnak antiseptikle temizlenir, distal-subungual tipte tırnağın proksimal-alt yüzeyinden subungual debris kazınır (en canlı mantar burada), yüzeyel beyaz tipte tırnak yüzeyinden kazıntı alınır. Bol miktarda örnek gerekir; hasta en az 2-4 hafta topikal, 3 ay sistemik antifungal almamış olmalıdır. KOH + kültür birlikte istenir; PCR duyarlılığı artırır."},
{k:"Mikoloji",s:"Mantar kan kültürlerinde duyarlılığı artıran yöntemler nelerdir?",c:"Özel fungal şişeler (mikoz-IC/F), lizis-sentrifügasyon (Isolator) tüpü — özellikle dimorfik mantarlar ve Malassezia için, inkübasyon süresinin uzatılması, yeterli kan hacmi. Candida kan kültürlerinin duyarlılığı yalnızca %50-70'tir; bu nedenle T2Candida, PCR ve beta-D-glukan gibi kültür dışı yöntemler destekleyici olarak kullanılır."},
{k:"Mikoloji",s:"Küf mantarlarında biyogüvenlik açısından nelere dikkat edilmelidir?",c:"Tüm küf kültürleri sınıf II biyogüvenlik kabininde açılmalı, tüp besiyeri (plak yerine) tercih edilmeli, plaklar bantlanmalıdır. Coccidioides, Histoplasma, Blastomyces ve Talaromyces marneffei BSL-3 gerektirir; laboratuvar kökenli enfeksiyon riski yüksektir. Kuşkulu koloni sarsılmadan, nemlendirilerek incelenmelidir."},
{k:"Mikoloji",s:"Termal dimorfizmin kültürde doğrulanması nasıl yapılır?",c:"25°C'de üreyen küf formundan alınan örnek zengin besiyerine (beyin-kalp infüzyonlu kanlı agar, sistein-kan) ekilip 37°C'de inkübe edilir ve maya formuna dönüşüm izlenir; bu işlem haftalar sürebilir ve risklidir. Günümüzde yerini DNA prob (AccuProbe), MALDI-TOF ve dizi analizi gibi hızlı ve güvenli yöntemler almıştır."},
{k:"Mikoloji",s:"Mantar tanımlamasında hangi genetik bölgeler dizilenir?",c:"ITS (internal transcribed spacer) bölgesi mantarlar için evrensel barkod olarak kabul edilir. Ek olarak D1/D2 (28S rDNA) mayalarda, beta-tubulin ve kalmodulin Aspergillus ve Penicillium'da, TEF1-α Fusarium'da tür ayrımı için kullanılır. Kompleks içi türlerin ayrımı (A. fumigatus complex) çoğu kez tek lokusla mümkün olmaz."},
{k:"Mikoloji",s:"Mikotoksinler ve klinik önemleri nelerdir?",c:"Aflatoksin (A. flavus/parasiticus): hepatosellüler karsinom, p53 mutasyonu. Okratoksin A (A. ochraceus, Penicillium): nefrotoksik. Fumonisin (Fusarium): özofagus kanseri, nöral tüp defekti. Deoksinivalenol/T-2 (Fusarium): kusma, alimenter toksik aleuki. Ergot alkaloidleri (Claviceps): vazokonstrüksiyon, gangren. Mikotoksikoz enfeksiyon değil, intoksikasyondur."},
{k:"Mikoloji",s:"Alerjik bronkopulmoner aspergilloz (ABPA) tanısında laboratuvar kriterleri nelerdir?",c:"Total IgE >1000 IU/mL, Aspergillus fumigatus'a özgül IgE ve IgG (presipitin) pozitifliği, A. fumigatus deri testi ani reaktivitesi, eozinofili, santral bronşektazi ve mukus tıkaçları. Astım veya kistik fibroz zemininde görülür; tedavi steroid ± itrakonazoldür. Kolonizasyon ile ayrımı serolojik yükseklik sağlar."},
{k:"Mikoloji",s:"Miçetoma (Madura ayağı) etkenleri nasıl ayrılır?",c:"Eumiçetoma (gerçek mantar: Madurella, Scedosporium) — granüller siyah veya beyaz, geniş septalı hifler, tedavi uzun süreli azol + cerrahi. Aktinomiçetoma (bakteriyel: Nocardia, Actinomadura, Streptomyces) — granüller sarı-kırmızı, ince (1 µm) filamentler, tedavi TMP-SMX/amikasin. Granül rengi, boyutu ve mikroskobisi ayrımın temelidir."},
{k:"Mikoloji",s:"Kromoblastomikoz ile feohifomikoz arasındaki fark nedir?",c:"Her ikisi de melanin içeren (dematiaceous, kahverengi) mantarlarla oluşur. Kromoblastomikozda dokuda patognomonik 'sklerotik/muriform cisimler' (bakır para hücreleri) görülür ve lezyon verrüköz-kroniktir. Feohifomikozda dokuda pigmente hif ve maya formları vardır; subkütan kist veya beyin apsesi (Cladophialophora bantiana) yapabilir."},
{k:"Mikoloji",s:"Trichosporon türlerinin klinik ve laboratuvar özellikleri nelerdir?",c:"Artrokonidyum ve blastokonidyum oluşturan, üreaz (+) mayalardır. Beyaz piedra ve nötropenik hastalarda yaygın trikosporonoz yapar. Kriptokok antijen testinde çapraz reaksiyonla yalancı pozitiflik verir. Ekinokandinlere doğal dirençlidir; tedavide vorikonazol tercih edilir."},
{k:"Mikoloji",s:"Candida idrar kültüründe üremesi her zaman tedavi gerektirir mi?",c:"Hayır. Asemptomatik kandidüri çoğunlukla kolonizasyondur; en etkili yaklaşım kateterin değiştirilmesi/çıkarılmasıdır. Tedavi endikasyonları: semptomatik sistit/piyelonefrit, nötropenik hasta, çok düşük doğum ağırlıklı yenidoğan ve ürolojik girişim planlanan hastalar. Flukonazol idrarda yüksek konsantrasyona ulaşır; ekinokandinler ulaşmaz."},
{k:"Mikoloji",s:"Mantar kültürlerinde inkübasyon süresi ve sıcaklığı nasıl planlanır?",c:"İki set: biri 25-30°C (küfler ve dimorfiklerin küf fazı), biri 35-37°C (mayalar, dimorfiklerin maya fazı). Yüzeyel mikozlarda 2-4 hafta, derin/sistemik mikozlarda 4-6 hafta tutulur. Plaklar haftada 2-3 kez incelenir, kuruma önlenir. Erken negatif rapor verilmemeli, ön rapor ile klinisyen bilgilendirilmelidir."},
/* ---------------- PARAZİTOLOJİ ---------------- */
{k:"Parazitoloji",s:"Dışkıda parazit aranmasında neden üç örnek istenir?",c:"Protozoon kist ve trofozoitleri ile helmint yumurtaları aralıklı (intermittan) atılır. Gün aşırı alınan 3 örnek duyarlılığı tek örneğe göre %60-70'ten %90'ın üzerine çıkarır. Örnekler baryumlu tetkik, antibiyotik ve antidiyareik ilaç sonrası 7-10 gün beklenerek alınmalıdır."},
{k:"Parazitoloji",s:"Dışkı örneğinde nativ-lugol preparatı neyi gösterir?",c:"Serum fizyolojikli (nativ) kısım hareketli trofozoitleri ve larvaları; lugollü kısım glikojen kitlesi ve çekirdek yapısını boyayarak kist morfolojisini gösterir. Lugol trofozoitleri öldürür, bu nedenle iki alan birlikte hazırlanır. Taze, sulu dışkı 30 dakika içinde incelenmelidir (trofozoitler hızla parçalanır)."},
{k:"Parazitoloji",s:"Formol-etil asetat çöktürme yöntemi nasıl çalışır?",c:"Dışkı formolle fikse edilir, etil asetat yağ ve debrisi çözüp üst faza taşır; santrifüj sonrası ağır parazit yapıları (yumurta, kist, larva) dipte toplanır. Duyarlılığı doğrudan incelemeye göre belirgin artırır. Ancak hareketli trofozoitleri görüntülemez ve yağlı/az yoğunluklu bazı yumurtalar için flotasyon tercih edilebilir."},
{k:"Parazitoloji",s:"Trikrom ve modifiye asit-fast boyalar parazitolojide ne için kullanılır?",c:"Trikrom (Wheatley) ve demir hematoksilen: bağırsak protozoonlarının (Entamoeba, Giardia) çekirdek yapısını ayrıntılı gösterir, tür ayrımı yapar. Modifiye asit-fast (Kinyoun): Cryptosporidium, Cystoisospora, Cyclospora ookistlerini kırmızı boyar. Modifiye trikrom (Weber) mikrosporidia sporları için kullanılır."},
{k:"Parazitoloji",s:"Entamoeba histolytica ile E. dispar / E. coli nasıl ayrılır?",c:"E. histolytica ve E. dispar morfolojik olarak ayrılamaz; ayrım dışkı antijen testi (adhezin ELISA) veya PCR ile yapılır. Eritrosit fagositozu yapan trofozoit E. histolytica lehinedir. E. coli (apatojen) ise 8 çekirdekli kist, kaba periferik kromatin ve eksantrik karyozomla ayrılır (E. histolytica kisti en fazla 4 çekirdeklidir, ince düzgün kromatin, santral karyozom)."},
{k:"Parazitoloji",s:"Amip karaciğer apsesinde laboratuvar tanı nasıl konur?",c:"Dışkıda parazit çoğunlukla bulunmaz (%10-40). Seroloji (IHA/ELISA) yüksek duyarlılıkla pozitiftir ve endemik olmayan bölgede tanısaldır. Apse aspiratı 'ançüez ezmesi' görünümündedir ve trofozoitler çoğunlukla apse duvarında bulunur, merkezde nadir görülür; PCR duyarlılığı artırır. Görüntüleme ile birlikte değerlendirilir."},
{k:"Parazitoloji",s:"Giardia intestinalis tanısında hangi yöntemler kullanılır?",c:"Dışkıda nativ-lugol (armut şeklinde, 2 çekirdekli, 'yüz' görünümlü trofozoit; oval 4 çekirdekli kist), dışkı antijen testi (ELISA/DFA, duyarlılığı yüksek), PCR. Dışkıda saptanamazsa duodenal aspirat veya Enterotest (string test). Yağlı, kötü kokulu ishal ve malabsorbsiyon tipiktir."},
{k:"Parazitoloji",s:"Cryptosporidium tanısı nasıl konur ve kimlerde ağır seyreder?",c:"Modifiye asit-fast boyama (4-6 µm kırmızı ookistler), DFA, dışkı antijen testi (EIA) ve multipleks PCR. AIDS hastalarında (CD4<100) kronik, hayatı tehdit eden ishal yapar; sağlıklı kişilerde kendini sınırlar. Klorlu suya dirençlidir, yüzme havuzu salgınlarına yol açar. Tedavi: nitazoksanit ve immün düzelme."},
{k:"Parazitoloji",s:"Cyclospora cayetanensis'in ayırt edici laboratuvar özelliği nedir?",c:"8-10 µm ookistler (Cryptosporidium'un iki katı), modifiye asit-fast ile değişken boyanma ('hayalet' hücreler) ve UV floresan mikroskopide otofloresans (mavi-yeşil) gösterir. Taze atıldığında sporsuz olduğu için doğrudan bulaşmaz, çevrede sporlanır. Taze meyve/yeşillik kaynaklı salgınlar; tedavi TMP-SMX."},
{k:"Parazitoloji",s:"Dientamoeba fragilis neden gözden kaçar?",c:"Kist formu yoktur, yalnız trofozoit atılır ve nativ incelemede kolayca parçalanır. Tanı için kalıcı boyalı preparat (trikrom) veya PCR gerekir; dışkı hemen fikse edilmelidir. Sıklıkla Enterobius vermicularis ile birlikte bulaşır ve kronik karın ağrısı, ishal yapar."},
{k:"Parazitoloji",s:"Blastocystis hominis'in klinik önemi ve tanısı nedir?",c:"Patojenitesi tartışmalıdır; yüksek yoğunlukta (×400 alanda ≥5) ve başka etken yoksa semptomlarla ilişkilendirilir. Nativ/boyalı preparatta merkezi vakuollü, 5-40 µm yuvarlak formlar görülür. Subtip (ST1-ST9) tayini PCR ile yapılır. Tedavi endikasyonu tartışmalı; metronidazol kullanılır."},
{k:"Parazitoloji",s:"Sıtma tanısında kalın damla ve ince yayma neyi sağlar?",c:"Kalın damla: eritrositler lizise uğratılır, 20-40 kat daha fazla kan taranır; parazit varlığını ve düşük parazitemiyi saptamada duyarlıdır. İnce yayma: morfoloji korunur; tür tayini ve parazitemi yüzdesinin hesaplanmasını sağlar. Giemsa pH 7.2 ile boyanır; negatifse 12-24 saat arayla 3 kez tekrarlanmalıdır."},
{k:"Parazitoloji",s:"Plasmodium türleri periferik yaymada nasıl ayrılır?",c:"P. falciparum: çoklu enfekte eritrosit, ince halka (signet ring), aplike formlar, muz şeklinde gametosit, Maurer çentikleri, şizont nadiren görülür, parazitemi yüksek. P. vivax/ovale: genç (retikülosit) eritrositleri tutar, hücre büyür, Schüffner noktalanması; ovale'de oval ve saçaklı eritrosit. P. malariae: bant formu trofozoit, papatya (rozet) şizont, yaşlı eritrosit."},
{k:"Parazitoloji",s:"Sıtma hızlı tanı testleri (RDT) hangi antijenleri saptar ve sınırlılıkları nelerdir?",c:"HRP-2 (yalnız P. falciparum, tedaviden sonra haftalarca pozitif kalır; bazı suşlarda pfhrp2/3 delesyonu yalancı negatiflik yapar), pLDH ve aldolaz (pan-Plasmodium, canlı paraziti gösterir). RDT parazitemi yüzdesini vermez; ağır sıtma izleminde mikroskopi zorunludur."},
{k:"Parazitoloji",s:"Ağır (komplike) falciparum sıtması laboratuvar ölçütleri nelerdir?",c:"Parazitemi >%5 (veya >%2 bağışık olmayanda), şizont/pigment taşıyan nötrofil görülmesi, hipoglisemi, metabolik asidoz (laktat >5), ağır anemi (Hb<7), böbrek yetmezliği, hiperbilirubinemi, hemoglobinüri, bilinç bozukluğu. Bu durumda IV artesunat ve parazitemi takibi (12 saatte bir) gerekir."},
{k:"Parazitoloji",s:"Toxoplasma gondii'nin bulaş yolları ve yaşam döngüsü nasıldır?",c:"Kesin konak kedidir (bağırsak epitelinde seksüel döngü, ookist atılımı). İnsanlara: ookist bulaşmış toprak/su/yiyecek, az pişmiş ette doku kisti (bradizoit), transplasental geçiş, organ/kan nakli ile bulaşır. İmmün baskılanmada bradizoitler taşizoite dönüşerek ensefalit yapar."},
{k:"Parazitoloji",s:"Leishmania tanısında hangi yöntemler kullanılır?",c:"Lezyon/kemik iliği/dalak aspiratından Giemsa yayması (makrofaj içinde amastigot – Leishman-Donovan cisimciği), NNN (Novy-MacNeal-Nicolle) besiyerinde promastigot kültürü, PCR (en duyarlı, tür tayini de yapar), viseral formda rK39 hızlı seroloji ve DAT. Montenegro deri testi kutanöz formda geçirilmiş enfeksiyonu gösterir."},
{k:"Parazitoloji",s:"Trypanosoma cruzi ile Afrika tripanozomlarının tanısı nasıl farklıdır?",c:"T. cruzi (Chagas): akut dönemde kanda tripomastigot, kronik dönemde seroloji (iki farklı test pozitifliği gerekir) ve PCR; ksenodiagnoz tarihsel yöntemdir. T. brucei (uyku hastalığı): kan, lenf nodu aspiratı ve BOS'ta hareketli tripomastigot; CATT tarama testi; evreleme için BOS incelemesi (hücre >5/µL veya parazit varlığı 2. evre) şarttır."},
{k:"Parazitoloji",s:"Babesia ile Plasmodium falciparum yaymada nasıl karıştırılır, ne ayırır?",c:"İkisi de ince halka formu yapar. Babesia'da: pigment (hemozoin) yoktur, hücre dışı formlar görülür, 4 halkadan oluşan patognomonik 'Malta haçı' tetrad görülebilir, gametosit ve şizont yoktur. Epidemiyoloji (kene teması, splenektomi) ve PCR ayrımı kesinleştirir."},
{k:"Parazitoloji",s:"Enterobius vermicularis tanısı nasıl konur?",c:"Selofan bant (Graham) yöntemi: sabah tuvalet ve yıkanma öncesi perianal bölgeye şeffaf bant yapıştırılıp lama aktarılır; asimetrik, bir yanı düz, D harfi şeklinde yumurtalar görülür. Dışkıda yumurta nadiren bulunur (%5-15). Duyarlılık için 3-5 ardışık sabah tekrarlanmalıdır."},
{k:"Parazitoloji",s:"Ascaris lumbricoides yumurtalarının morfolojik özellikleri nelerdir?",c:"Döllenmiş yumurta: 45-75 µm, kalın üç katmanlı duvar, dışta kabartılı (mamillated) albüminöz tabaka, safra ile kahverengi. Döllenmemiş yumurta: daha uzun (90 µm'ye kadar), ince albüminöz tabaka, düzensiz granüler içerik. Dekortike formda dış tabaka yoktur ve hookworm yumurtası ile karışabilir."},
{k:"Parazitoloji",s:"Strongyloides stercoralis tanısında hangi yöntem tercih edilir ve neden?",c:"Dışkıda yumurta değil rabditiform larva atılır ve sayısı azdır; rutin inceleme duyarlılığı düşüktür. Agar plak kültürü (larva izleri) veya Baermann huni yöntemi tercih edilir; ayrıca seroloji ve PCR kullanılır. Otoenfeksiyon nedeniyle steroid/HTLV-1 varlığında hiperenfeksiyon sendromu ve Gram negatif sepsis gelişebilir — steroid öncesi tarama önemlidir."},
{k:"Parazitoloji",s:"Kancalı kurt (Ancylostoma/Necator) tanısı ve morfolojik ayrımı nasıl yapılır?",c:"Dışkıda ince şeffaf duvarlı, 4-8 blastomerli oval yumurta (türler arası ayrım yumurtayla yapılamaz). Ayrım erişkin ağız yapısı ile: Ancylostoma duodenale'de iki çift diş, Necator americanus'ta kesici plaklar. Larva ayrımı için kültür (Harada-Mori) gerekir. Demir eksikliği anemisi ve eozinofili tipiktir."},
{k:"Parazitoloji",s:"Trichuris trichiura yumurtası nasıl tanınır?",c:"50-55 µm, fıçı/limon şeklinde, kalın kahverengi duvarlı, her iki kutbunda şeffaf tıkaç (mukoid plug) bulunur. Ağır enfestasyonda rektal prolapsus ve kronik ishal yapar. Tedavi mebendazol/albendazoldür."},
{k:"Parazitoloji",s:"Taenia saginata ile T. solium nasıl ayrılır ve hangisi daha tehlikelidir?",c:"Yumurtalar aynıdır (radyal çizgili, 30-40 µm), ayrım proglottid ve skoleks ile yapılır: T. saginata gravid proglottidinde 15-20 yan uterus dalı, skoleksinde çengel yok; T. solium'da 7-13 dal ve çengelli rostellum vardır. T. solium yumurtasının yutulması nörosistiserkoza yol açar — bu yüzden daha tehlikelidir ve proglottid parçalanmadan alınmalıdır."},
{k:"Parazitoloji",s:"Echinococcus granulosus kist sıvısında ne aranır ve neden dikkatli olunmalıdır?",c:"Kist sıvısında protoskoleksler ve çengelli 'hidatik kum' aranır. Ponksiyon kist içeriğinin dökülmesine ve anafilaksiye yol açabileceği için tanı amaçlı iğne biyopsisi geleneksel olarak kaçınılır; görüntüleme (WHO kist sınıflaması) ve seroloji ile tanı konur. PAIR işlemi albendazol koruması altında deneyimli merkezde yapılır."},
{k:"Parazitoloji",s:"Schistosoma türleri yumurta morfolojisi ile nasıl ayrılır?",c:"S. mansoni: yan (lateral) dikenli, dışkıda. S. haematobium: terminal (uç) dikenli, idrarda (öğlen saatlerinde alınan örnek). S. japonicum: küçük, rudimenter yan çıkıntılı, dışkıda. Kesin konak insan, ara konak tatlı su salyangozudur; serkerler deriden girer. S. haematobium mesane skuamöz hücreli karsinomu ile ilişkilidir."},
{k:"Parazitoloji",s:"Fasciola hepatica ile Fasciolopsis buski yumurtaları nasıl ayrılır?",c:"İkisi de büyük (130-150 µm), operkullü, safra boyalı ve mikroskobik olarak neredeyse aynıdır; ayrım klinik ve epidemiyolojiktir (Fasciola: su teresi, karaciğer/safra yolu, eozinofili ve karaciğer lezyonları; Fasciolopsis: su kestanesi, bağırsak). Fasciola'da seroloji erken dönemde (yumurta atılımı öncesi) değerlidir; tedavi triklabendazoldür."},
{k:"Parazitoloji",s:"Filaria tanısında kan örneği ne zaman alınmalıdır?",c:"Periyodisiteye göre: Wuchereria bancrofti ve Brugia malayi gece periyodiktir (22:00-04:00), Loa loa gündüz periyodiktir (10:00-14:00). Kalın damla, Knott konsantrasyonu veya membran filtrasyonu ile mikrofilarya aranır. Onchocerca volvulus kanda değil, deri kesisi (skin snip) ile aranır. Kılıf varlığı ve kuyruk çekirdek dizilimi tür ayrımını sağlar."},
{k:"Parazitoloji",s:"Trichinella spiralis tanısı nasıl konur?",c:"Klinik üçlü: periorbital ödem, miyalji, eozinofili + CPK/LDH yüksekliği. Kesin tanı kas biyopsisinde (deltoid, gastroknemius) kapsüllenmiş larvaların görülmesi; seroloji (ELISA) 3. haftadan sonra pozitifleşir. Az pişmiş domuz/yaban domuzu eti ile bulaşır. Dışkıda parazit aranmaz."},
{k:"Parazitoloji",s:"Trichomonas vaginalis tanısında hangi yöntemler kullanılır?",c:"Taze vajinal akıntının serum fizyolojikle nativ incelemesi (titrek hareketli, armut şeklinde trofozoit; duyarlılık yalnız %50-60), kültür (Diamond besiyeri), hızlı antijen testi ve en duyarlı yöntem NAAT. Pap smearda rastlantısal görülebilir ama özgüllüğü düşüktür. Kist formu yoktur, cinsel yolla bulaşır, partner de tedavi edilir."},
{k:"Parazitoloji",s:"Acanthamoeba ve Naegleria fowleri enfeksiyonları nasıl ayrılır?",c:"Naegleria: sıcak tatlı suda yüzme sonrası, kribriform plaktan girer, primer amebik meningoensefalit (PAM) yapar; BOS'ta hareketli trofozoitler görülür, hızlı ve öldürücüdür. Acanthamoeba: granülomatöz amebik ensefalit (kronik, immünsüpresif) ve kontakt lensle ilişkili keratit yapar; dokuda kist + trofozoit görülür. Kültürde E. coli kaplı non-nutrient agarda 'iz' bırakarak ürerler."},
{k:"Parazitoloji",s:"Mikrosporidia tanısında hangi boyalar kullanılır?",c:"Modifiye trikrom (Weber kromotrop) — 1-3 µm sporlar pembe-kırmızı, bazılarında çapraz/kuşak şeklinde bant; kalkoflor beyazı ile floresan; kesin tanı için elektron mikroskobu (polar tüp sarımları) veya PCR. Enterocytozoon bieneusi ve Encephalitozoon türleri AIDS hastalarında kronik ishal yapar."},
{k:"Parazitoloji",s:"Dışkı parazit incelemesinde mikroskobik ölçüm neden önemlidir?",c:"Yumurta ve kistlerin ayrımı büyük ölçüde boyuta dayanır (Cryptosporidium 4-6 µm vs. Cyclospora 8-10 µm; Taenia 30-40 µm vs. Fasciola 130-150 µm). Bu nedenle okülerdeki mikrometre her objektif için kalibre edilmeli ve ölçüm raporda belirtilmelidir."},
{k:"Parazitoloji",s:"Eozinofili hangi parazitlerde beklenir, hangilerinde beklenmez?",c:"Doku invazyonu yapan helmintlerde belirgindir: Strongyloides, Toxocara, Trichinella, Schistosoma, Fasciola, filaria, Ascaris'in akciğer göçü (Löffler). Lümende kalan erişkin helmintlerde (Taenia, Enterobius) hafif veya yoktur. Protozoonlarda tipik olarak eozinofili görülmez (istisna: Cystoisospora, Sarcocystis, Dientamoeba)."},
{k:"Parazitoloji",s:"Larva migrans tipleri nelerdir?",c:"Viseral larva migrans: Toxocara canis/cati — çocukta hepatomegali, eozinofili, ELISA ile tanı. Oküler larva migrans: retinal granülom, retinoblastom ayırıcı tanısı. Kutanöz larva migrans: Ancylostoma braziliense — kumda çıplak ayak, ilerleyici serpiginöz döküntü. Tanı çoğunlukla klinik ve serolojiktir; dışkıda parazit bulunmaz."},
{k:"Parazitoloji",s:"Sarcoptes scabiei (uyuz) tanısı nasıl konur?",c:"Tünel kazıntısı (mineral yağ ile), dermoskopide 'delta uçağı/jet izi' işareti, KOH preparatında akar, yumurta veya dışkı (skibala) görülmesi. Klasik uyuzda akar sayısı 10-15 iken kabuklu (Norveç) uyuzda milyonlarcadır ve oldukça bulaşıcıdır. Tedavi permetrin veya ivermektin, temaslılarla birlikte."},
{k:"Parazitoloji",s:"Parazitolojide örnek fiksatifleri nelerdir?",c:"SAF (sodyum asetat-asetik asit-formalin): hem konsantrasyon hem kalıcı boyamaya uygun, cıva içermez. %10 formalin: konsantrasyon ve helmint yumurtası için iyi, kalıcı boyama için uygun değil. PVA (polivinil alkol): kalıcı boyalı preparat için mükemmel, klasik formu cıva içerir (çinko/bakır bazlı alternatifleri vardır). MIF ve Schaudinn diğer seçeneklerdir. Antijen testi ve PCR için fiksatifsiz taze/dondurulmuş örnek gerekir."},
{k:"Parazitoloji",s:"Bağırsak parazitozlarında multipleks PCR panellerinin yeri nedir?",c:"Giardia, Cryptosporidium, E. histolytica, Cyclospora ve bazı helmintleri yüksek duyarlılıkla, hızlı ve gözlemciden bağımsız saptar. Sınırlılıkları: yalnız panelde yer alan etkenleri bulur (nadir helmintleri kaçırır), canlı-ölü ayrımı yapmaz, tedavi takibinde yanıltabilir ve maliyeti yüksektir. Mikroskopinin tümüyle yerini almaz."},
{k:"Parazitoloji",s:"Kan parazitlerinde Giemsa boyamanın pH'sı neden kritiktir?",c:"pH 7.2'lik tamponlu Giemsa, Schüffner ve Maurer noktalanmalarının görünmesini sağlar; bu noktalanmalar tür ayrımında belirleyicidir. Düşük pH'da (asidik) eritrosit içi noktalanmalar boyanmaz ve P. vivax ile P. falciparum ayrımı yapılamaz."},
{k:"Parazitoloji",s:"Hipereozinofili ve Katayama ateşi nedir?",c:"Katayama ateşi akut şistozomiyaz tablosudur: enfeksiyondan 2-8 hafta sonra ateş, ürtiker, hepatosplenomegali ve belirgin eozinofili ile seyreder; henüz yumurta atılımı başlamadığı için dışkı incelemesi negatiftir ve tanı seroloji/klinik öykü ile konur. Yumurta araması 6-12 hafta sonra tekrarlanmalıdır."},
{k:"Parazitoloji",s:"Toxoplasma tanısında hangi durumda PCR tercih edilir?",c:"Konjenital enfeksiyon şüphesinde amniyon sıvısında (18. gebelik haftasından sonra), immünsüpresif hastada serebral toksoplazmoz için BOS'ta, oküler toksoplazmozda vitreus/aköz sıvıda ve dissemine hastalıkta kanda. Bu gruplarda antikor yanıtı güvenilmez olduğundan seroloji tek başına yetersiz kalır."},
{k:"Parazitoloji",s:"İdrarda parazit aranması hangi durumlarda yapılır ve örnek nasıl alınır?",c:"S. haematobium yumurtası için 10:00-14:00 arasında, tercihen egzersiz sonrası, terminal idrar (son kısım) toplanır; 24 saatlik idrar da kullanılabilir. Filtrasyon veya santrifüj sonrası sediment incelenir. Ayrıca Trichomonas, mikrofilarya (şilüri) ve nadiren Enterobius yumurtası saptanabilir."},
{k:"Parazitoloji",s:"Balantioides (Balantidium) coli'nin özellikleri nelerdir?",c:"İnsanı enfekte eden tek silli protozoondur ve en büyük protozoondur (trofozoit 50-100 µm). Domuz rezervuardır. Silleriyle hızlı dönerek hareket eder; makronükleus böbrek şeklindedir. Kolonda amip benzeri ülser ve dizanteri yapar; tedavi tetrasiklin veya metronidazoldür."},
{k:"Parazitoloji",s:"Hymenolepis nana'nın diğer sestodlardan farkı nedir?",c:"Ara konak zorunlu değildir; yumurta doğrudan enfektiftir ve otoenfeksiyon yapabilir, bu nedenle ağır enfestasyon ve immünsüpresifte yaygın hastalık görülür. Yumurtası 30-50 µm, iki kabuklu, iç kabuğun kutuplarından çıkan filamentler (polar flament) taşır; H. diminuta'da flament yoktur. Tedavi prazikuanteldir."},
{k:"Parazitoloji",s:"Diphyllobothrium latum hangi eksikliğe yol açar ve yumurtası nasıldır?",c:"Vitamin B12'yi konaktan önce emerek megaloblastik anemi yapar. Yumurtası operkullü ve karşı uçta küçük bir çıkıntı (abopercular knob) taşır, 58-76 µm. Çiğ/az pişmiş tatlı su balığı ile bulaşır (plerocercoid larva)."},
{k:"Parazitoloji",s:"Dışkıda Charcot-Leyden kristalleri ne anlama gelir?",c:"Eozinofil galektin-10 proteininden oluşan renksiz, iğne/elmas şeklinde kristallerdir. Eozinofilik bir bağırsak yanıtını gösterir; parazitoz (özellikle amebiyaz, helmintler) veya alerjik/eozinofilik gastrointestinal hastalık düşündürür. Etkene özgü değildir, ipucu niteliğindedir."},
{k:"Parazitoloji",s:"Parazitolojide kalite kontrol nasıl sağlanır?",c:"Referans preparatlar ve fikse edilmiş pozitif örneklerden oluşan koleksiyon, oküler mikrometre kalibrasyonu, boyaların her seride kontrol preparatıyla çalışılması, iki bağımsız okuyucu ile teyit, dış kalite programlarına katılım ve dijital görüntü arşivi. Ayrıca teknik personelin düzenli morfoloji eğitimi gereklidir."},
{k:"Parazitoloji",s:"Antiparaziter ilaçların başlıca etki mekanizmaları nelerdir?",c:"Benzimidazoller (albendazol, mebendazol): β-tubuline bağlanıp mikrotübül polimerizasyonunu ve glukoz alımını engeller. Prazikuantel: Ca2+ geçirgenliğini artırıp tegümenti bozar (sestod, trematod). İvermektin: glutamatla açılan klorür kanallarını açar, paralizi yapar. Metronidazol: anaerop koşulda nitro grubu indirgenip DNA'yı kırar. Artemisininler: hem ile etkileşip serbest radikal üretir."},
{k:"Parazitoloji",s:"Nörosistiserkoz tanısında laboratuvar yaklaşımı nasıldır?",c:"Görüntüleme (BT/MR'da kistler, skoleks, kalsifikasyon) temeldir; serum EITB (Western blot, lentil lektinle saflaştırılmış glikoprotein) yüksek özgüllüktedir ve çoklu kistli olguda duyarlıdır. Tek kistli ve kalsifiye olgularda seroloji negatif olabilir. BOS ELISA destekleyicidir. Dışkıda Taenia yumurtası aranması taşıyıcılık için önemlidir."},
{k:"Parazitoloji",s:"Demodex türleri hangi durumlarda patojen kabul edilir?",c:"Demodex folliculorum ve D. brevis normal deri florasında bulunur; kıl folikülü başına ≥5 akar veya standart yüzeysel deri biyopsisinde cm2'de ≥5 akar patojen yoğunluk kabul edilir. Rozasea, blefarit ve pitiriyazis foliculorum ile ilişkilendirilir. Tanı: selofan bant, standart yüzeysel deri biyopsisi, dermoskopi."},
{k:"Parazitoloji",s:"Kan ve doku parazitlerinde serolojinin sınırlılıkları nelerdir?",c:"Geçirilmiş ile aktif enfeksiyonu ayırt edemez, endemik bölgede özgüllüğü düşer, immünsüprese hastada yalancı negatif olur, akraba türlerle çapraz reaksiyon verir (Leishmania-Trypanosoma, Echinococcus-Taenia, Toxocara-Ascaris) ve tedavi sonrası uzun süre pozitif kalarak takipte yanıltır."},
{k:"Parazitoloji",s:"Ara konak, kesin konak, rezervuar ve vektör kavramlarını tanımlayın.",c:"Kesin konak: parazitin erişkin veya seksüel formunun bulunduğu konak (sıtmada sivrisinek, toksoplazmada kedi). Ara konak: larva/aseksüel formun geliştiği konak (insan, sıtmada). Rezervuar: parazitin doğada sürdüğü canlı kaynak. Vektör: paraziti taşıyan artropod; biyolojik vektörde parazit çoğalır/gelişir, mekanik vektörde yalnız taşınır."},
{k:"Parazitoloji",s:"Dışkı örneğinin parazitoloji için reddedilme nedenleri nelerdir?",c:"İdrar veya su ile karışmış örnek (trofozoitleri parçalar), baryumlu inceleme sonrası 7-10 gün içinde alınmış örnek, kuru/bekletilmiş örnek, yanlış veya sızdıran kap, etiketsiz örnek, aynı gün içinde gönderilmiş birden çok örnek ve antibiyotik/antidiyareik kullanımı sırasında alınan örnek."},
{k:"Parazitoloji",s:"Kist, ookist, trofozoit ve sporokist arasındaki farklar nelerdir?",c:"Trofozoit: beslenen, hareketli, çoğalan ve çevrede kısa süre yaşayan aktif form. Kist: dayanıklı duvarlı, bulaşıcı dinlenme formu (Giardia, Entamoeba). Ookist: kokssidiyanların (Cryptosporidium, Toxoplasma, Cystoisospora) zigottan gelişen dayanıklı formu; içinde sporokist ve sporozoitler bulunur. Bulaşıcılık genellikle kist/ookist formu ile olur."},
/* ---------------- IFA (İMMÜNFLORESAN) ---------------- */
{k:"IFA",s:"Direkt ve indirekt immünfloresan yöntemleri arasındaki fark nedir?",c:"Direkt IFA'da floresan işaretli antikor doğrudan hedef antijene bağlanır; hızlıdır, arka plan düşüktür, klinik örnekte antijen aramada kullanılır (RSV, influenza, Pneumocystis, Legionella). İndirekt IFA'da önce işaretsiz hasta antikoru antijene bağlanır, sonra işaretli antiglobulin eklenir; sinyal amplifikasyonu nedeniyle daha duyarlıdır ve hasta serumunda antikor aramada kullanılır (ANA, Rickettsia)."},
{k:"IFA",s:"IFA'da hangi florokromlar kullanılır ve hangi dalga boylarında uyarılır?",c:"FITC (fluorescein isothiocyanate): uyarım ~495 nm, emisyon ~519 nm, elma yeşili. TRITC/rodamin: uyarım ~550 nm, emisyon ~570 nm, kırmızı. Alexa Fluor serisi daha parlak ve fotostabildir. DAPI çekirdek karşıt boyaması için (uyarım UV ~358, emisyon ~461 nm, mavi) kullanılır."},
{k:"IFA",s:"Floresan mikroskopta uyarım filtresi, dikroik ayna ve bariyer filtresi ne işe yarar?",c:"Uyarım (eksitasyon) filtresi kaynaktan yalnız florokromu uyaracak dalga boyunu geçirir. Dikroik ayna kısa dalga boyunu örneğe yansıtır, örnekten dönen uzun dalga boylu emisyonu geçirir. Bariyer (emisyon) filtresi kalan uyarım ışığını bloke eder, yalnız floresan sinyali göze/kameraya ulaştırır. Bu üçlü 'filtre küpü' özgül sinyal-gürültü oranını belirler."},
{k:"IFA",s:"Fotobeyazlanma (photobleaching) nedir, nasıl azaltılır?",c:"Florokromun uzun süreli uyarım ışığı altında geri dönüşsüz olarak kimyasal bozunup sinyal vermemesidir. Azaltmak için: uyarım şiddetini ve süresini sınırlamak, antifade (p-fenilendiamin, DABCO, ticari mounting) kapatma ortamı kullanmak, preparatları karanlıkta ve +4°C'de saklamak, duyarlı kamera ile kısa pozlama yapmak."},
{k:"IFA",s:"IFA'da otofloresans nedir ve nasıl ayırt edilir?",c:"Dokudaki elastin, kollajen, lipofuksin, flavinler, eritrositler ve bazı fiksatiflerin (glutaraldehit) kendiliğinden ışıma yapmasıdır; genellikle geniş spektrumlu, sarımsı-yeşil ve yapısal dağılımlıdır. Ayrımı için: işaretsiz kontrol (yalnız konjugatsız preparat), farklı emisyon kanalında kontrol, Sudan Black B veya bakır sülfat ile söndürme, kırmızı/uzak kırmızı florokrom tercihi."},
{k:"IFA",s:"IFA testlerinde hangi kontroller çalışılmalıdır?",c:"Her seride pozitif kontrol serumu (paterni doğrular), zayıf pozitif kontrol (duyarlılık sınırını gösterir), negatif kontrol (arka plan/non-spesifik bağlanma), konjugat kontrolü (birincil antikorsuz — konjugatın kendi bağlanması) ve substrat/hücre kontrolü. Kontroller beklenen sonucu vermezse hasta sonuçları raporlanmaz."},
{k:"IFA",s:"ANA (antinükleer antikor) IFA'da HEp-2 hücresi neden tercih edilir?",c:"İnsan epitelyal hücre hattıdır; büyük çekirdek ve belirgin nükleolus içerir, bölünen (mitotik) hücreler bulundurur ve insan antijen repertuarını taşır. Mitotik figürler sentromer, NuMA ve kromozom ilişkili paternlerin ayrımını sağlar; dondurulmuş hayvan dokusunda saptanamayan SSA/Ro gibi antijenler HEp-2'de (özellikle Ro-transfekte hatlarda) görünür."},
{k:"IFA",s:"ANA IFA'da titre ve patern nasıl raporlanır?",c:"En az 1/80 (bazı laboratuvarlarda 1/40 ve 1/160) tarama dilüsyonunda başlanır, pozitifse iki kat dilüsyonlarla son pozitif dilüsyon titre olarak verilir. Rapor hem titreyi hem paterni (ICAP sınıflaması: AC-1 homojen, AC-2/4 benekli, AC-3 sentromer, AC-8-10 nükleolar, AC-21 sitoplazmik retiküler/AMA gibi) içermelidir. Sitoplazmik paternler de raporlanır."},
{k:"IFA",s:"ANCA IFA'da c-ANCA ve p-ANCA paternleri nasıl oluşur ve neyi gösterir?",c:"Etanolle fikse nötrofillerde: c-ANCA granüler sitoplazmik boyanma (PR3 antikoru; granülomatöz polianjiit), p-ANCA perinükleer boyanma (MPO antikoru; mikroskopik polianjiit, EGPA). p-ANCA bir artefakttır: etanol fiksasyonunda katyonik MPO çekirdeğe göç eder. Formalin fikse preparatta p-ANCA sitoplazmik görünür — bu ANA kaynaklı yalancı p-ANCA'yı ayırır. Doğrulama ELISA ile PR3/MPO ölçümüdür."},
{k:"IFA",s:"Direkt immünfloresan deri ve böbrek biyopsilerinde ne için kullanılır?",c:"Dokuda in vivo birikmiş immünglobulin ve kompleman depozitlerini gösterir. Örnek: pemfigusta epidermis içi 'balık ağı' IgG; büllöz pemfigoidde bazal membranda lineer IgG/C3; dermatitis herpetiformiste dermal papillada granüler IgA; IgA nefropatisinde mezangiyal IgA; lupus nefritinde 'tam ev' (full house) paterni. Doku dondurulmuş kesit olarak (Michel taşıma sıvısı) gönderilmelidir."},
{k:"IFA",s:"Solunum yolu virüslerinde DFA örneği nasıl olmalıdır?",c:"Nazofaringeal aspirat veya fırçalama ile bol epitel hücresi içeren örnek gerekir; yalnız mukus veya az hücreli örnek yetersizdir. Kabul edilebilirlik için preparatta yeterli sayıda (≥20) silindirik epitel hücresi bulunmalıdır. Hücre içi granüler/apple-green floresan pozitif kabul edilir. Duyarlılığı PCR'den düşüktür ve büyük ölçüde yerini moleküler testlere bırakmıştır."},
{k:"IFA",s:"IFA'da non-spesifik bağlanma nasıl azaltılır?",c:"Bloklama (normal serum, BSA, kazein), yeterli yıkama (PBS-Tween), konjugat dilüsyonunun titre edilmesi, Fc reseptörlerinin bloklanması, uygun fiksatif seçimi ve inkübasyon süresi/sıcaklığının optimize edilmesi. Ayrıca yüksek konjugat konsantrasyonu arka planı artırır; çapraz adsorbe edilmiş ikincil antikorlar tercih edilmelidir."},
{k:"IFA",s:"Rickettsia ve Coxiella serolojisinde IFA nasıl kullanılır?",c:"IFA altın standarttır. Çift serumda (2-4 hafta arayla) ≥4 kat titre artışı tanısaldır. Q ateşinde faz ayrımı kritiktir: faz II antikor baskınlığı akut enfeksiyonu, faz I IgG ≥1/800 kronik (endokardit, vasküler) enfeksiyonu gösterir. Akut dönemde ilk serum negatif olabilir, tedavi serolojiyi beklemeden başlatılır."},
{k:"IFA",s:"Antikor sınıfına özgü IFA (IgM/IgG) çalışılırken hangi hatalara dikkat edilir?",c:"Romatoid faktör yalancı IgM pozitifliği, yüksek özgül IgG'nin antijen bölgelerini doldurup IgM'i baskılaması (kompetisyon → yalancı negatif) ve maternal IgG'nin bebeğe geçişi. Önlem: serumun RF/IgG absorbanı ile ön işlemden geçirilmesi veya µ-capture formatının kullanılması."},
{k:"IFA",s:"IFA substratları (hücre, doku, örümcek) nasıl seçilir?",c:"Aranan antijene göre: HEp-2 hücreleri ANA için; primat karaciğer/böbrek/mide üçlü doku AMA, ASMA, LKM, parietal hücre antikorları için; maymun özofagus endomisyum antikoru (çölyak) için; etanol/formalin fikse nötrofil ANCA için; enfekte hücre kültürü (Vero, HEL) viral ve riketsiyal antikorlar için. Doğru substrat seçilmezse özgül antikor kaçırılır."},
{k:"IFA",s:"Floresan mikroskopta konfokal ve geniş alan (widefield) farkı nedir?",c:"Widefield mikroskopta örneğin tüm derinliği aydınlatılır ve odak dışı ışık görüntüyü bulanıklaştırır. Konfokalde iğne deliği (pinhole) odak dışı ışığı eler, ince optik kesitler ve 3B rekonstrüksiyon sağlar; çözünürlük ve kontrast yüksektir. Rutin tanısal IFA widefield ile yapılır; konfokal daha çok araştırma ve ko-lokalizasyon çalışmalarında kullanılır."},
{k:"IFA",s:"IFA preparatlarının saklanması ve okunması ile ilgili kurallar nelerdir?",c:"Okuma tercihen aynı gün, karanlık odada, aynı mikroskop ve aynı lamba saatleriyle yapılmalıdır; cıva/LED kaynağın yaşlanması sinyali azaltır ve düzenli kaydedilmelidir. Preparatlar okunamayacaksa antifade ile kapatılıp karanlıkta +4°C'de saklanır. Okuyucular arası uyum düzenli olarak değerlendirilmeli, kuşkulu paternler ikinci okuyucuya doğrulatılmalıdır."},
{k:"IFA",s:"Otomatik IFA okuma sistemlerinin avantaj ve sınırlılıkları nelerdir?",c:"Avantaj: okuyucu subjektifliğini azaltır, dijital arşiv ve izlenebilirlik sağlar, iş akışını hızlandırır, pozitif/negatif ayrımında yüksek uyum gösterir. Sınırlılık: karışık paternleri ve nadir paternleri yanlış sınıflayabilir, sitoplazmik paternleri kaçırabilir; pozitif sonuçların uzman tarafından doğrulanması gerekir."},
{k:"IFA",s:"Legionella DFA'nın avantaj ve dezavantajları nelerdir?",c:"Avantaj: hızlı sonuç, alt solunum yolu örneğinde doğrudan bakteri gösterimi, kültürden önce yönlendirici olabilir. Dezavantaj: duyarlılığı düşük (%25-70), yalnız kullanılan konjugatın kapsadığı serogrupları saptar, teknik deneyim gerektirir, Pseudomonas ve Bacteroides ile çapraz reaksiyon bildirilmiştir. Kültür ve idrar antijeni ile birlikte değerlendirilir."},
{k:"IFA",s:"FITC/protein (F/P) oranı konjugat kalitesini nasıl etkiler?",c:"F/P oranı bir antikor molekülüne bağlı florokrom sayısını gösterir. Çok düşükse sinyal zayıf olur; çok yüksekse antikorun yükü değişir, non-spesifik bağlanma ve arka plan artar, ayrıca sönümleme (quenching) görülür. Tanısal konjugatlarda genellikle 2-4 mol FITC/mol IgG hedeflenir ve konjugat çalışma dilüsyonu blok titrasyonla belirlenir."},
{k:"IFA",s:"Evans mavisi karşıt boyası neden kullanılır?",c:"Arka plandaki hücre ve dokuyu kırmızı boyayarak elma yeşili FITC sinyalinin kontrastını artırır ve hafif non-spesifik yeşil otofloresansı maskeler. Böylece özgül boyanmanın ayırt edilmesi kolaylaşır. Aşırı kullanımı zayıf pozitif sinyalleri baskılayabilir."},
{k:"IFA",s:"IFA ile ELISA arasında tanısal iş akışında nasıl bir ilişki kurulur?",c:"Genellikle ELISA/CLIA tarama (yüksek verim, sayısal, otomatize), IFA doğrulama ve patern tayini (ANA, ANCA, riketsiya) veya tersi kullanılır. ANA için IFA hâlâ referans yöntemdir; ANCA'da IFA + özgül ELISA birlikte önerilir. İki yöntemin uyuşmazlığı klinikle birlikte değerlendirilir ve üçüncü bir yöntemle çözülür."},
{k:"IFA",s:"Toxoplasma Sabin-Feldman boya testi nedir?",c:"Canlı Toxoplasma taşizoitleri hasta serumu ve komplemanla (aksesuar faktör) inkübe edilir; özgül antikor varsa parazit membranı hasarlanır ve metilen mavisi ile boyanmaz. Boyanmayan parazit oranı %50'ye ulaştığı dilüsyon titredir. Çok duyarlı ve özgüldür, referans yöntem kabul edilir; ancak canlı parazit gerektirdiği için yalnız uzman merkezlerde yapılır."},
{k:"IFA",s:"İmmünfloresans ile immünhistokimya arasındaki fark nedir?",c:"IFA'da işaret florokromdur, floresan mikroskop gerekir, çoklu işaretleme kolaydır, sinyal zamanla söner ve morfolojik ayrıntı sınırlıdır (çoğunlukla dondurulmuş kesit). İHK'da işaret enzimdir (HRP/AP), kromojenle kalıcı renk oluşur, ışık mikroskobuyla okunur, parafin kesitte morfoloji korunur ve preparat yıllarca saklanabilir."},
{k:"IFA",s:"Çoklu (multipleks) immünfloresan boyamada nelere dikkat edilmelidir?",c:"Emisyon spektrumları örtüşmeyen florokromlar seçilmeli, farklı türlerde üretilmiş birincil antikorlar kullanılmalı, çapraz adsorbe ikincil antikorlar tercih edilmeli, tek boyalı kontrollerle taşma (bleed-through) değerlendirilmeli ve sıralı (sequential) boyama ile çapraz reaksiyon engellenmelidir."},
{k:"IFA",s:"IFA sonuçlarını etkileyen preanalitik faktörler nelerdir?",c:"Hemolizli, lipemik veya bakteri üremiş serum; tekrarlayan dondurma-çözme; uygunsuz saklama sıcaklığı; yanlış antikoagülan; örneğin fiksasyon öncesi kuruması; doku örneğinin formalinde bekletilmesi (dondurulmuş kesit gereken DIF için); hasta serumunun sulandırılmasında hata. Bunların hepsi zayıf sinyal veya yüksek arka plana yol açar."},
{k:"IFA",s:"Endomisyum antikoru (EMA) IFA'da nasıl değerlendirilir?",c:"Maymun özofagus veya insan göbek kordonu kesitinde düz kas demetlerini saran bağ dokusunda (endomisyum) IgA sınıfı bal peteği/ağ şeklinde floresan görülür. Çölyak hastalığında özgüllüğü ~%99'dur. IgA eksikliğinde yalancı negatif olur; bu nedenle total IgA ölçümü eş zamanlı yapılmalı, eksiklikte IgG bazlı testler kullanılmalıdır."},
{k:"IFA",s:"IFA'da 'prozon' benzeri yüksek titre etkisi görülür mü?",c:"Evet; çok yüksek antikor titrelerinde düşük dilüsyonda boyanma paterni bulanıklaşıp yanlış değerlendirilebilir veya bazı substratlarda sinyal beklenenden zayıf okunabilir. Ayrıca yoğun homojen ANA, birlikte bulunan benekli veya nükleolar paterni maskeleyebilir. Çözüm: ileri dilüsyonlarda okuma yapmak ve paterni yüksek dilüsyonda doğrulamak."},
{k:"IFA",s:"Kuduz tanısında DFA'nın yeri nedir?",c:"Beyin dokusunda (beyin sapı, serebellum, hipokampus) kuduz nükleoproteinine karşı işaretli antikorla yapılan DFA, kuduzun altın standart post-mortem tanı yöntemidir; dakikalar-saatler içinde sonuç verir. Negri cisimciklerinin histolojik gösterimi daha az duyarlıdır. Ante-mortem tanıda ense derisi biyopsisi DFA, tükürük RT-PCR ve kornea baskı preparatı kullanılır."},
{k:"IFA",s:"Pneumocystis jirovecii DFA'sı neden tercih edilebilir?",c:"Monoklonal antikor hem kist hem trofik formları boyar; bu nedenle yalnız kistleri gösteren GMS ve toluidin mavisine göre daha duyarlıdır ve daha hızlı okunur. İndüklenmiş balgamda duyarlılık farkı özellikle belirgindir. PCR daha duyarlıdır ancak kolonizasyonu da saptadığından kantitatif yorum gerekir."},
{k:"IFA",s:"IFA titrelerinin laboratuvarlar arası karşılaştırılması neden zordur?",c:"Substrat (hücre hattı, doku kaynağı), fiksasyon yöntemi, konjugat F/P oranı ve dilüsyonu, mikroskop ışık kaynağı, filtre setleri ve okuyucu eşiği laboratuvarlar arasında farklıdır. Bu nedenle titreler ancak aynı laboratuvarda, aynı koşullarda anlamlı biçimde karşılaştırılabilir; hasta izleminde örneklerin aynı laboratuvarda çalışılması önerilir."},
{k:"IFA",s:"FISH (floresan in situ hibridizasyon) mikrobiyolojide nasıl kullanılır?",c:"Floresan işaretli oligonükleotid problar bakteri ribozomal RNA'sına hibridize olur; kan kültürü şişesinden veya doku kesitinden bir-iki saat içinde tür düzeyinde tanı verir (PNA-FISH ile S. aureus/KNS, E. coli/Klebsiella, Candida albicans/glabrata ayrımı). Ayrıca kültürde üretilemeyen ve biyofilm içindeki bakterilerin in situ gösteriminde kullanılır."},
{k:"IFA",s:"IFA'da lam ve kuyucuk hazırlığında hangi teknik hatalar sık görülür?",c:"Kuyucuklar arası taşma (çapraz kontaminasyon), preparatın inkübasyon sırasında kuruması, yetersiz veya aşırı yıkama, hava kabarcıkları, kapatma ortamının fazla/az olması, lamın ters okunması ve konjugatın ışıkta bekletilmesi. Nemli kamara kullanımı ve standardize pipetleme bu hataları azaltır."},
{k:"IFA",s:"Anti-dsDNA için Crithidia luciliae IFA testi nasıl çalışır?",c:"Crithidia luciliae adlı hemoflagellatın kinetoplastı saf, protein içermeyen çift sarmallı DNA içerir. Hasta serumundaki anti-dsDNA antikorları kinetoplastı boyar; özgüllüğü çok yüksektir (SLE için), ancak duyarlılığı Farr radyoimmünoassay ve ELISA'dan düşüktür. Çekirdek boyanması tek başına pozitiflik sayılmaz."},
{k:"IFA",s:"IFA raporunda hangi bilgiler bulunmalıdır?",c:"Kullanılan yöntem ve substrat, tarama dilüsyonu ve son titre, gözlenen patern(ler) (varsa ICAP kodu), kontrollerin uygunluğu, örnek kalitesine ilişkin uyarılar, yöntemin sınırlılıkları ve gerekli doğrulama testi önerisi. Klinik yorum, testin tek başına tanı koymadığı vurgusuyla verilmelidir."},
{k:"IFA",s:"HEp-2 hücrelerinde mitotik hücrelerin değerlendirilmesi neden önemlidir?",c:"Mitoz plağının boyanma durumu paternleri ayırır: sentromer antikorunda metafaz plağı boyanır (AC-3); homojen paternde kromatin kitlesi boyanır; benekli paternde interfaz çekirdek boyanırken mitotik kromatin boyanmaz (AC-4); NuMA, iğ iplikçikleri ve midbody paternleri yalnız mitotik hücrelerde ayırt edilir. Mitotik hücre görülmeyen preparat yetersiz kabul edilir."},
{k:"IFA",s:"IFA'da 'yalancı pozitif' sonuçların başlıca kaynakları nelerdir?",c:"Otofloresans, yüksek konjugat konsantrasyonu, yetersiz yıkama, kurumuş preparat, heterofil ve anti-hayvan antikorları, romatoid faktör, doku kesitindeki nekroz ve kristal birikimleri, hatalı filtre seti kullanımı ve deneyimsiz okuyucunun yapısal boyanmayı özgül sinyal sanması."},
{k:"IFA",s:"Kantitatif floresan ölçümü (MFI) IFA'da neden kullanılmaz?",c:"Klasik IFA görsel/subjektif bir yöntemdir; ışık kaynağının şiddeti, fotobeyazlanma, preparat kalınlığı ve okuyucu farkı nedeniyle yoğunluk standardize edilemez. Kantitatif ölçüm için akım sitometrisi veya kalibre dijital görüntüleme sistemleri gerekir; IFA'da sonuç titre olarak, yani en yüksek pozitif dilüsyon ile yarı-kantitatif verilir."},
/* ---------------- FLOW SİTOMETRİ ---------------- */
{k:"Flow Sitometri",s:"Akım sitometrisinin temel bileşenleri nelerdir?",c:"Sıvı sistemi (hidrodinamik odaklama ile hücrelerin tek sıra hâlinde akması), optik sistem (lazerler, filtreler, dikroik aynalar, dedektörler), elektronik sistem (sinyalin dijitalleştirilmesi, pulse işleme) ve veri analiz yazılımı. Bazı cihazlarda ayrıca hücre ayırma (sorting) modülü bulunur."},
{k:"Flow Sitometri",s:"FSC ve SSC neyi ölçer?",c:"FSC (forward scatter, ileri saçılım) küçük açıda saçılan ışıktır ve hücre büyüklüğü ile orantılıdır. SSC (side scatter, yan saçılım) 90°'de saçılan ışıktır ve hücre içi granülarite/kompleksite ile orantılıdır. Lökositlerde FSC/SSC grafiği lenfosit (düşük/düşük), monosit (orta) ve granülosit (yüksek SSC) popülasyonlarını ayırır."},
{k:"Flow Sitometri",s:"Hidrodinamik odaklama nedir ve neden gereklidir?",c:"Örnek akımı, daha hızlı akan kılıf (sheath) sıvısı ile sarılarak laminer akış içinde daraltılır; hücreler tek sıra hâlinde ve lazer ışınının aynı noktasından geçer. Böylece her hücre eşit aydınlatma alır, sinyal tekrarlanabilir olur ve aynı anda iki hücrenin okunması (coincidence) azalır."},
{k:"Flow Sitometri",s:"Kompensasyon nedir ve neden gereklidir?",c:"Bir florokromun emisyon spektrumu komşu dedektörün filtre aralığına taşar (spektral örtüşme). Kompensasyon, bu taşan sinyalin matematiksel olarak çıkarılmasıdır. Tek boyalı kontroller ile hesaplanır; yanlış kompensasyon yalancı pozitif veya yalancı negatif popülasyonlar yaratır. Spektral sitometrelerde bunun yerine spektral unmixing kullanılır."},
{k:"Flow Sitometri",s:"FMO (Fluorescence Minus One) kontrolü nedir?",c:"Panelde yer alan bir florokrom dışındaki tüm antikorların bulunduğu kontroldür. Çoklu renkli panellerde kompensasyondan artakalan taşma nedeniyle oluşan yayılım hatasını (spreading error) gösterir ve pozitif/negatif kapı sınırının doğru çizilmesini sağlar. Özellikle zayıf/sürekli ifade edilen belirteçlerde (CD25, PD-1) şarttır."},
{k:"Flow Sitometri",s:"İzotip kontrolü nedir, sınırlılıkları nelerdir?",c:"Aynı izotip, konjugat ve üretici firmadan, hedefe özgü olmayan antikordur; Fc reseptörü aracılı ve non-spesifik bağlanmayı göstermeyi amaçlar. Ancak farklı F/P oranı ve farklı bağlanma özellikleri nedeniyle gerçek arka planı yansıtmayabilir; modern kılavuzlar izotip yerine FMO ve biyolojik (internal negatif) kontrolleri önerir."},
{k:"Flow Sitometri",s:"Gating (kapılama) stratejisi nasıl kurulur?",c:"Önce debris ve artefaktlar dışlanır (FSC-A/SSC-A), sonra doubletler çıkarılır (FSC-A/FSC-H veya FSC-W), ardından canlılık boyası ile ölü hücreler dışlanır, gerekirse CD45/SSC ile lökosit alt grupları ayrılır ve son olarak hedef popülasyon özgül belirteçlerle kapılanır. Her kapı bir üst kapının yüzdesi olarak raporlanır."},
{k:"Flow Sitometri",s:"Doublet ayrımı neden ve nasıl yapılır?",c:"İki hücrenin birlikte lazerden geçmesi tek ve yanlış (çift parlak) bir olay olarak okunur; bu, ploidi analizinde ve nadir olay saptamada ciddi hata yaratır. Ayrım için pulse geometrisi kullanılır: tek hücrelerde alan (A) ile yükseklik (H) orantılıdır; doubletlerde alan/genişlik artarken yükseklik orantılı artmaz, bu nedenle FSC-A/FSC-H grafiğinde çizgi dışına düşerler."},
{k:"Flow Sitometri",s:"CD45/SSC kapılaması ne işe yarar?",c:"CD45 yoğunluğu ve yan saçılım birlikte kullanılarak lenfosit (parlak CD45, düşük SSC), monosit (orta-parlak CD45, orta SSC), granülosit (orta CD45, yüksek SSC), blast (zayıf CD45, düşük-orta SSC, 'blast bölgesi') ve eritroid öncüller (CD45 negatif) ayrılır. Lösemi/lenfoma immünfenotiplemesinde temel kapılama stratejisidir."},
{k:"Flow Sitometri",s:"CD4 T lenfosit sayımında ikili ve tekli platform yöntemleri nedir?",c:"İkili platform: akım sitometrisinden yüzde, hematoloji analizöründen mutlak lökosit/lenfosit sayısı alınır ve çarpılarak mutlak sayı hesaplanır; iki cihaz hatası birikir. Tekli platform: tüpe bilinen sayıda floresan sayım boncuğu (bead) eklenir veya hacim ölçümü yapılır, mutlak sayı doğrudan hesaplanır; daha doğru ve tekrarlanabilirdir, HIV izleminde tercih edilir."},
{k:"Flow Sitometri",s:"HIV izleminde CD4 sayısı nasıl yorumlanır?",c:"CD4 <200 hücre/µL (veya %14) AIDS tanımlayıcıdır ve Pneumocystis profilaksisi gerektirir; <100'de Toxoplasma ve Cryptococcus, <50'de MAC ve CMV riski artar. CD4/CD8 oranı normalde >1'dir, ilerlemiş HIV'de tersine döner. Akut enfeksiyon, kortikosteroid, splenektomi ve diürnal değişim geçici dalgalanma yapar; tedavi kararı için trend ve viral yük birlikte değerlendirilir."},
{k:"Flow Sitometri",s:"Akım sitometrisi mikrobiyolojide hangi amaçlarla kullanılır?",c:"İdrar örneklerinde hızlı bakteri/lökosit tarama (kültür yükünü azaltma), antimikrobiyal duyarlılığın hızlı belirlenmesi (membran potansiyeli ve canlılık boyalarıyla), gıda ve su mikrobiyolojisinde canlı ama üretilemeyen (VBNC) bakterilerin sayımı, mantar hücre döngüsü analizi, sıtma parazitemi taraması ve mikrobiyom çalışmalarında bakteri sayımı."},
{k:"Flow Sitometri",s:"Canlılık (viabilite) boyaları nasıl çalışır?",c:"Membran bütünlüğü bozulmuş hücrelere giren DNA bağlayıcı boyalar kullanılır: propidyum iyodür, 7-AAD, DAPI (fikse edilmemiş örnek için) ve amin-reaktif sabitlenebilir canlılık boyaları (fiksasyon gereken protokoller için). Canlı hücreler boyayı dışlar. Ölü hücreler antikorları non-spesifik bağladığı için canlılık kapısı yalancı pozitifliği önler."},
{k:"Flow Sitometri",s:"Anneksin V / propidyum iyodür ile apoptoz nasıl değerlendirilir?",c:"Apoptozda fosfatidilserin membranın dış yüzüne döner ve kalsiyum varlığında Anneksin V'ye bağlanır. Anneksin V(+)/PI(−): erken apoptoz; Anneksin V(+)/PI(+): geç apoptoz veya sekonder nekroz; Anneksin V(−)/PI(+): nekroz; her ikisi negatif: canlı hücre. Bağlama tamponu mutlaka kalsiyum içermelidir."},
{k:"Flow Sitometri",s:"Lizis-yıkama ve lizis-yıkamasız yöntemler arasındaki fark nedir?",c:"Lizis-yıkamasız (no-wash) yöntemde eritrositler lizise uğratılır ancak yıkama yapılmaz; hücre kaybı olmaz, mutlak sayım için uygundur ancak serbest antikor nedeniyle arka plan yüksektir. Lizis-yıkama yönteminde bağlanmamış antikor uzaklaştırılır, sinyal-gürültü daha iyidir ama hücre kaybı ve popülasyon oranlarında sapma olabilir."},
{k:"Flow Sitometri",s:"Yüzey ve hücre içi boyama arasındaki teknik fark nedir?",c:"Yüzey belirteçleri canlı hücrede doğrudan boyanır. Hücre içi boyama için fiksasyon (paraformaldehit) ve permeabilizasyon gerekir: sitoplazmik antijenler (MPO, cCD3, cCD79a) için saponin/deterjan, nükleer antijenler (TdT, Ki-67, FoxP3) için daha güçlü permeabilizasyon (metanol veya özel tampon) kullanılır. Önce yüzey, sonra hücre içi boyama yapılmalıdır."},
{k:"Flow Sitometri",s:"Sitokin üretimini hücre içi olarak ölçerken neden brefeldin A veya monensin kullanılır?",c:"Bu ajanlar Golgi aracılı protein sekresyonunu bloke eder; üretilen sitokinler hücre içinde birikir ve boyanabilir düzeye ulaşır. Aksi hâlde sitokin hücre dışına salınır ve saptanamaz. Uyarım (PMA/iyonomisin veya özgül antijen) ile birlikte 4-6 saat uygulanır; uzun süre toksik olabilir ve CD4 gibi yüzey belirteçlerini aşağı düzenleyebilir."},
{k:"Flow Sitometri",s:"Akım sitometrisinde hassasiyet ve çözünürlük nasıl tanımlanır?",c:"Hassasiyet (sensitivity): saptanabilecek en az floresan molekül sayısı (MESF ile ifade edilir) ve dedektör gürültüsü ile sınırlıdır. Çözünürlük: iki popülasyonu birbirinden ayırabilme yeteneğidir ve stain index ile ölçülür [(pozitif medyan − negatif medyan)/(2 × negatif SD)]. Parlak florokromu zayıf ifade edilen antijene atamak çözünürlüğü artırır."},
{k:"Flow Sitometri",s:"Panel tasarımında florokrom seçimi nasıl yapılır?",c:"Zayıf ifade edilen antijenlere parlak florokromlar (PE, APC, BV421), yüksek ifade edilenlere zayıf florokromlar (FITC, PerCP) atanır. Aynı hücrede birlikte bulunan (ko-eksprese) belirteçler spektral olarak uzak kanallara yerleştirilir. Tandem boyaların (PE-Cy7, APC-Cy7) ışığa ve fiksasyona duyarlılığı hesaba katılır; lazer ve filtre konfigürasyonu panelin sınırını belirler."},
{k:"Flow Sitometri",s:"Tandem florokromlar nasıl çalışır ve hangi sorunları yaratır?",c:"Bir donör (PE, APC) uyarılıp enerjisini FRET ile akseptöre (Cy5, Cy7) aktarır ve daha uzun dalga boyunda emisyon sağlar; tek lazerle daha çok renk kullanılmasına olanak verir. Sorun: tandem bozunması (ışık, ısı, fiksatif, dondurma-çözme) donör sinyalinin artmasına ve kompensasyon hatasına yol açar. Bu nedenle kompensasyon kontrolleri aynı lot tandem ile hazırlanmalıdır."},
{k:"Flow Sitometri",s:"Minimal rezidüel hastalık (MRD) analizinde akım sitometrisinin rolü nedir?",c:"Lösemi hücrelerinin normal hematopoetik hücrelerden farklı antijen ifade paternini (LAIP — leukemia associated immunophenotype veya 'different from normal' yaklaşımı) kullanarak 10^-4-10^-6 düzeyinde nadir hücre saptar. Yüksek olay sayısı (≥10^6), standardize panel (EuroFlow) ve deneyimli yorumcu gerektirir; tedaviye yanıtın ve nüks riskinin en güçlü göstergelerindendir."},
{k:"Flow Sitometri",s:"PNH (paroksismal noktürnal hemoglobinüri) tanısında akım sitometrisi nasıl kullanılır?",c:"GPI-bağlı proteinlerin (CD55, CD59) ve FLAER'in (floresan aerolizin, GPI çapasına doğrudan bağlanır) eksikliği gösterilir. Eritrositlerde CD59 ile tip I/II/III klonlar, granülosit ve monositlerde FLAER + CD24/CD14 ile klon boyutu belirlenir. Granülosit analizi transfüzyon ve hemolizden etkilenmediği için daha güvenilirdir; yüksek duyarlıklı protokollerle %0.01'e kadar klon saptanabilir."},
{k:"Flow Sitometri",s:"CD34+ kök hücre sayımında ISHAGE protokolü nedir?",c:"Sıralı kapılama: CD45+ olaylar → CD34+/CD45zayıf hücreler → düşük SSC kapısı → doublet ve debris dışlama → mutlak sayım boncukları ile hücre/µL hesaplanması. Canlılık için 7-AAD eklenir. Standardize edilmiş bu strateji, aferez ürününün yeterliliği (genellikle ≥2x10^6 CD34+/kg) kararı için kullanılır."},
{k:"Flow Sitometri",s:"Akım sitometrisinde nadir olay analizinde nelere dikkat edilir?",c:"Yeterli sayıda olay toplanmalı (hedef popülasyondan en az 50-100 olay, toplam 10^5-10^6 olay), taşıma (carryover) önlenmeli, otofloresan ve ölü hücreler dışlanmalı, boş tüp (blank) ile arka plan belirlenmeli, kapılar FMO ile doğrulanmalı ve istatistiksel güven aralığı (Poisson) raporlanmalıdır."},
{k:"Flow Sitometri",s:"Akım sitometrisi için kan örneği nasıl alınıp saklanmalıdır?",c:"Genellikle K2-EDTA (immünfenotipleme, mutlak sayım) veya heparin (fonksiyonel testler, hücre içi sitokin) kullanılır. Örnek oda sıcaklığında tutulmalı, buzdolabına konmamalı ve tercihen 24-48 saat içinde çalışılmalıdır (bazı belirteçler için 6 saat). Pıhtı, hemoliz ve aşırı gecikme hücre kaybı ve yalancı sonuç yaratır."},
{k:"Flow Sitometri",s:"Hücre döngüsü analizi akım sitometrisiyle nasıl yapılır?",c:"DNA'ya stokiyometrik bağlanan boya (propidyum iyodür + RNaz, DAPI) kullanılır; DNA içeriği histogramında G0/G1 (2n), S (ara), G2/M (4n) fazları ayrılır. Doublet dışlama zorunludur (G1 doubleti G2/M gibi görünür). Aneuploidi DNA indeksi ile değerlendirilir. BrdU/EdU ile S fazına aktif giren hücreler özgül olarak işaretlenebilir."},
{k:"Flow Sitometri",s:"Akım sitometrisinde kalite kontrol nasıl yürütülür?",c:"Günlük olarak standart floresan boncuklarla optik hizalama, CV ve dedektör voltajı kontrol edilir; Levey-Jennings grafikleriyle izlenir. Kompensasyon matrisi lot/ayar değişiminde yenilenir. Cihaz temizliği ve taşıma kontrolü yapılır, sıvı sistemi basıncı izlenir. Ayrıca dış kalite programlarına katılım ve personel yeterlilik değerlendirmesi gerekir."},
{k:"Flow Sitometri",s:"Stain index nedir ve nasıl kullanılır?",c:"Stain index = (pozitif popülasyon medyanı − negatif popülasyon medyanı) / (2 × negatif popülasyonun standart sapması). Bir florokrom-antikor kombinasyonunun ayırma gücünü sayısal olarak ifade eder. Panel optimizasyonunda antikor titrasyonu için kullanılır: en yüksek stain index'i veren antikor konsantrasyonu seçilir, bu genellikle doygunluk noktasının hemen altındadır."},
{k:"Flow Sitometri",s:"Antikor titrasyonu neden yapılmalıdır?",c:"Aşırı antikor arka planı ve non-spesifik bağlanmayı artırır, maliyeti yükseltir; yetersiz antikor popülasyonu tam boyamaz ve yalancı negatiflik yaratır. Her yeni lot ve her yeni hücre tipi için seri dilüsyonla stain index hesaplanarak optimum konsantrasyon belirlenmelidir. Hücre sayısı ve boyama hacmi de titrasyonda sabit tutulmalıdır."},
{k:"Flow Sitometri",s:"Spektral akım sitometrisi geleneksel sitometriden nasıl farklıdır?",c:"Geleneksel cihazda her florokrom için dar bantlı bir dedektör vardır. Spektral cihazda tüm emisyon spektrumu 30-60 dedektörle kaydedilir ve her florokromun 'spektral imzası' referans alınarak unmixing yapılır. Böylece spektrumları çok benzeyen florokromlar ayırt edilebilir, 30-40 renkli paneller kurulabilir ve otofloresans ayrı bir parametre olarak çıkarılabilir."},
{k:"Flow Sitometri",s:"Kütle sitometrisi (CyTOF) nedir?",c:"Antikorlar florokrom yerine nadir toprak metal izotopları ile işaretlenir; hücreler iyonlaştırılıp kütle spektrometresiyle analiz edilir. Spektral örtüşme ve otofloresans neredeyse yoktur, aynı anda 40-50 parametre ölçülebilir. Dezavantajları: hücre yok edilir (sorting yapılamaz), akış hızı düşüktür, maliyeti yüksektir ve duyarlılığı floresana göre bazı belirteçlerde daha düşüktür."},
{k:"Flow Sitometri",s:"Hücre ayırma (cell sorting) nasıl çalışır?",c:"Akış hücresinden çıkan sıvı, piezoelektrik titreşimle damlacıklara ayrılır. Kapı kriterlerine uyan hücreyi taşıyan damlacık yüklenir ve saptırıcı plakalar arasından geçerken elektrik alanı ile toplama tüpüne yönlendirilir. Saflık, verim ve hücre canlılığı arasında denge kurulur; aerosol oluşumu nedeniyle enfeksiyöz örneklerde biyogüvenlik önlemleri (BSL-2/3 kabinli sorter) gerekir."},
{k:"Flow Sitometri",s:"Bakteriyel analizde akım sitometrisinin zorlukları nelerdir?",c:"Bakteriler ökaryot hücrelerden çok küçüktür (0.3-2 µm); FSC sinyali elektronik gürültü ve debris düzeyine yakındır. Çözüm: SSC'yi tetikleyici (trigger) parametre yapmak, nükleik asit boyaları (SYBR Green, SYTO) ile bakteriyi debristen ayırmak, düşük gürültülü dedektör ve filtrelenmiş kılıf sıvısı kullanmak ve boncukla kalibrasyon yapmaktır."},
{k:"Flow Sitometri",s:"Akım sitometrik antibiyotik duyarlılık testi nasıl çalışır?",c:"Bakteri antibiyotikle kısa süre (1-4 saat) inkübe edilir; membran potansiyeli (DiOC2, bis-oksonol), membran bütünlüğü (propidyum iyodür) veya nükleik asit içeriği değişimi ölçülür. Duyarlı suşlarda depolarizasyon ve boya girişi artar. Klasik yönteme göre saatler kazandırır; ancak standardizasyon ve klinik sınır değerlerinin yerleşmemiş olması yaygınlaşmasını sınırlar."},
{k:"Flow Sitometri",s:"İdrar akım sitometrisi kültür iş yükünü nasıl azaltır?",c:"Otomatize idrar analizörleri (ör. UF serisi) bakteri ve lökosit sayısını floresan akım sitometrisiyle dakikalar içinde verir. Belirlenen eşiğin altındaki örnekler yüksek negatif prediktif değerle 'kültür gerektirmez' olarak ayrılır, böylece plak sayısı ve iş yükü %30-50 azalır. Eşik değerler her laboratuvarın kendi popülasyonunda kültürle karşılaştırılarak doğrulanmalıdır."},
{k:"Flow Sitometri",s:"BOS örneklerinin akım sitometrisinde özel zorlukları nelerdir?",c:"Hücre sayısı çok düşüktür ve hücreler hızla bozulur (2 saat içinde belirgin kayıp). Önlem: örneğin hemen işlenmesi, hücre koruyucu taşıma ortamı (RPMI, serum veya ticari stabilizatör) eklenmesi, düşük hacim protokolleri ve nadir olay analizinin kurallarına uyulması. Sitolojiye göre lenfomatöz tutulumu saptamada daha duyarlıdır."},
{k:"Flow Sitometri",s:"Lenfoma tanısında klonalitenin akım sitometrisiyle gösterilmesi nasıl olur?",c:"B hücrelerinde yüzey hafif zincir kısıtlaması aranır: normal kappa/lambda oranı 0.9-3.0'dır; >3 veya <0.5 klonaliteyi düşündürür, hafif zincir kaybı da anlamlıdır. T hücrelerinde klonalite yüzey belirteçleriyle güvenilir gösterilemez; TCR Vβ repertuar analizi veya moleküler klonalite (TCR gen yeniden düzenlenmesi) gerekir. Anormal antijen ifadesi (CD5+CD23+ B hücre gibi) destekleyicidir."},
{k:"Flow Sitometri",s:"Bazofil aktivasyon testi (BAT) nedir?",c:"Alerjen ile uyarılan tam kanda bazofillerin (CCR3+/CD123+HLA-DR−) yüzeyinde CD63 ve CD203c ifadesindeki artış akım sitometrisiyle ölçülür. İlaç, besin ve venom alerjilerinde in vivo provokasyona alternatif, in vitro fonksiyonel testtir. Pozitif (anti-IgE/fMLP) ve negatif kontroller zorunludur; bazı kişilerde bazofiller yanıtsızdır (non-responder)."},
{k:"Flow Sitometri",s:"HLA-B27 taraması akım sitometrisiyle nasıl yapılır ve sınırlılığı nedir?",c:"Tam kanda monoklonal anti-HLA-B27 antikoru ile lenfositler boyanır, floresan yoğunluğu eşik değerle karşılaştırılır. Hızlı ve ucuzdur; ancak HLA-B7 gibi çapraz reaksiyon veren alleller nedeniyle sınırda sonuçlar çıkabilir, bu olgular moleküler yöntemle (PCR-SSP/SSO) doğrulanmalıdır."},
{k:"Flow Sitometri",s:"Fetomaternal kanama (Kleihauer alternatifi) akım sitometrisiyle nasıl ölçülür?",c:"Anti-HbF veya anti-D antikorlarıyla maternal dolaşımdaki fetal eritrositler işaretlenir ve yüzdesi belirlenir. Kleihauer-Betke asit elüsyon yöntemine göre daha objektif, tekrarlanabilir ve duyarlıdır; anti-D dozunun (Rh immünglobulin) hesaplanmasında kullanılır. Maternal F hücreleri (HbF içeren erişkin eritrositleri) yorumda ayırt edilmelidir."},
{k:"Flow Sitometri",s:"Trombosit fonksiyon ve aktivasyon analizinde hangi belirteçler kullanılır?",c:"CD62P (P-selektin, alfa granül salınımı), CD63 (yoğun granül), aktive GPIIb/IIIa'ya özgül PAC-1 antikoru ve lökosit-trombosit agregatları. Örnek hemen işlenmeli, aktivasyonu önlemek için geniş iğneyle, turnikesiz alınmalı ve sitrat/CTAD ile stabilize edilmelidir. Glanzmann trombastenisi (CD41/CD61 eksikliği) ve Bernard-Soulier (CD42 eksikliği) tanısında da kullanılır."},
{k:"Flow Sitometri",s:"Primer immün yetmezlik taramasında akım sitometrisinin yeri nedir?",c:"Lenfosit alt grup sayımı (T/B/NK paterni SCID tiplerini ayırır), DHR 123 testi ile nötrofil oksidatif patlaması (kronik granülomatöz hastalık), CD18/CD11b ile lökosit adezyon defekti, BTK protein ifadesi (XLA), perforin/granzim (HLH), CD40L (hiper IgM) ve naif/hafıza T hücre oranı değerlendirmesi. Fonksiyonel testler mutlaka sağlıklı kontrolle eşzamanlı çalışılır."},
{k:"Flow Sitometri",s:"DHR (dihidrorodamin) testi nasıl yorumlanır?",c:"PMA ile uyarılan nötrofillerde NADPH oksidaz üretilen hidrojen peroksit dihidrorodamin 123'ü floresan rodamin 123'e çevirir. Kronik granülomatöz hastalıkta floresan artışı yoktur veya çok azdır. X'e bağlı taşıyıcı annelerde iki popülasyon (bimodal) görülür — bu patern taşıyıcılığı gösterir. Miyeloperoksidaz eksikliğinde DHR yanıtı azalabilir, yalancı pozitif yorumdan kaçınılmalıdır."},
{k:"Flow Sitometri",s:"Akım sitometrisi verileri hangi dosya formatında saklanır ve neden önemlidir?",c:"FCS (Flow Cytometry Standard) formatı — güncel sürüm FCS 3.1/3.2 — ham olay verilerini ve cihaz/örnek meta verilerini birlikte taşır. Ham veri saklandığı için analiz sonradan farklı kapılama ile tekrarlanabilir, denetlenebilir ve merkezler arasında paylaşılabilir. Yalnız yüzde raporu saklamak yeniden değerlendirmeyi olanaksız kılar."},
{k:"Flow Sitometri",s:"Akım sitometrisinde logaritmik ve bi-eksponansiyel (logicle) ölçek arasındaki fark nedir?",c:"Logaritmik ölçek geniş dinamik aralığı sıkıştırır ama sıfır ve negatif değerleri (kompensasyon sonrası oluşan) gösteremez; olaylar eksende yığılır. Bi-eksponansiyel/logicle ölçek sıfır çevresinde doğrusal, yüksek değerlerde logaritmiktir; negatif popülasyonu doğru dağıtır ve yanlış kapı çizimini önler."},
{k:"Flow Sitometri",s:"Akım sitometrisinde abort ve coincidence oranları neyi gösterir?",c:"Elektronik sistem bir olayı işlerken ikinci bir olay gelirse ('coincidence') veri kaybolur veya hatalı kaydedilir; abort oranı bu kayıpların yüzdesidir. Yüksek örnek akış hızı ve yoğun örnek bu oranı artırır. Doğru sayım için örnek seyreltilmeli ve akış hızı düşürülmelidir; genellikle abort oranı %2-5'in altında tutulur."},
{k:"Flow Sitometri",s:"Sitometri sonuçlarının raporlanmasında hangi bilgiler bulunmalıdır?",c:"Örnek tipi ve alınma/işlenme zamanı, kullanılan panel ve klonlar, kapılama stratejisi, toplam olay sayısı, her popülasyonun yüzdesi ve (varsa) mutlak sayısı, kontrollerin uygunluğu, teknik sınırlılıklar (hemoliz, gecikme, düşük hücre) ve klinik yorum. Anormal fenotipler tanımlayıcı olarak (aberran ifade dahil) belirtilmelidir."},
{k:"Flow Sitometri",s:"EuroFlow standardizasyonu neyi amaçlar?",c:"Cihaz ayarlarının (boncuklarla hedef MFI'ye kalibrasyon), antikor klonlarının, florokromların, boyama protokollerinin ve analiz yazılımının standardize edilmesiyle farklı merkezlerin verilerinin karşılaştırılabilir ve birleştirilebilir olmasını sağlar. Böylece referans veri tabanlarına karşı otomatik popülasyon tanımlama ve güvenilir MRD izlemi mümkün olur."},
{k:"Flow Sitometri",s:"Akım sitometrisinde biyogüvenlik açısından nelere dikkat edilmelidir?",c:"Analiz edilen örnekler potansiyel enfeksiyöz kabul edilir (HIV, HBV, HCV, M. tuberculosis). Sorting sırasında aerosol oluşur; kapalı, HEPA filtreli ve gerekirse BSL-3 düzeyinde sorter kullanılmalıdır. Örnekler mümkünse fikse edilmeli (%1-2 paraformaldehit), atık ve kılıf sıvısı dezenfekte edilmeli, kişisel koruyucu ekipman kullanılmalıdır."},
{k:"Flow Sitometri",s:"Akım sitometrisinde yalancı sonuçların başlıca nedenleri nelerdir?",c:"Yanlış kompensasyon, doubletlerin dışlanmaması, ölü hücrelerin non-spesifik antikor bağlaması, Fc reseptörü aracılı bağlanma (blok yapılmaması), tandem bozunması, yetersiz/aşırı antikor, örnek yaşlanması, pıhtı ve debris, yanlış kapı çizimi ve yetersiz olay sayısı. Kontrollerin doğru kurulması bu hataların çoğunu önler."},
{k:"Flow Sitometri",s:"Lenfosit alt grup sayımının normal erişkin referans aralıkları yaklaşık nedir?",c:"Yaklaşık değerler: CD3+ T hücre %55-84 (700-2100/µL), CD4+ %31-60 (300-1400/µL), CD8+ %13-41 (200-900/µL), CD4/CD8 oranı 1.0-3.6, CD19+ B hücre %5-20 (100-500/µL), CD16/56+ NK hücre %5-25 (90-600/µL). Çocuklarda değerler yaşa göre belirgin farklıdır; her laboratuvar kendi referans aralığını doğrulamalıdır."},
{k:"Flow Sitometri",s:"Fc reseptör bloklama neden gereklidir?",c:"Monosit, makrofaj, B hücre ve NK hücrelerindeki Fc reseptörleri antikorların Fc kısmını antijenden bağımsız olarak bağlar ve yalancı pozitif boyanma yaratır. Önlem: insan IgG, ticari Fc blok reaktifleri veya ilgisiz serum ile ön inkübasyon; ayrıca F(ab')2 fragmanlı antikor kullanımı. Özellikle zayıf sinyalli ve miyeloid popülasyonlarda kritiktir."},
{k:"Flow Sitometri",s:"Boncuk temelli multipleks immünoassay (CBA/Luminex) akım sitometrisiyle nasıl çalışır?",c:"Farklı floresan yoğunlukta kodlanmış boncuk setlerinin her biri farklı bir yakalama antikoru taşır. Örnek eklendiğinde her analit kendi boncuğuna bağlanır; ortak raportör (PE) ile miktar ölçülür. Boncuğun kod kanalı analiti, raportör kanalı konsantrasyonu belirler. Tek örnekte onlarca sitokin/antikor aynı anda ölçülebilir; standart eğri ile kantitasyon yapılır."},
{k:"Flow Sitometri",s:"Akım sitometrisinde 'trigger' (eşik) parametresi ne işe yarar?",c:"Cihazın bir olayı kaydetmeye başlaması için aşılması gereken sinyal eşiğidir. Genellikle FSC kullanılır; debrisi ve elektronik gürültüyü ayıklar. Ancak küçük partiküllerde (bakteri, ekstraselüler vezikül, trombosit) FSC yetersiz kalır ve SSC ya da floresan kanalı (nükleik asit veya CD41 boyası) tetikleyici olarak seçilir. Yanlış eşik hedef popülasyonun tümüyle kaybedilmesine yol açabilir."},
];
